window.PMM_NAHJ_TRANSCRIPT_ACCEPT({"group":"wisdoms","number":400,"source":"حکمت 400.docx","mode":"explicit-parts","parts":["حکمت 400\nبخش اول\nمتن:\nوَ قَالَ (عليه السلام): الْعَيْنُ حَقٌّ، وَ الرُّقَى حَقٌّ، وَ السِّحْرُ حَقٌّ\nترجمه:\nامام (عليه السّلام) فرمود: «چشم زخم» حق است و تعويذ (دعايى كه براى دفع چشم زخم است) نيز حق است و سِحر حق است\nتفسیر:\nوَ قَالَ (علیه السلام): الْعَیْنُ حَقٌّ\nامام علی علیه‌السلام :«چشم زخم» حق است،\n💠وَ الرُّقَى حَقٌّ\nو تعویذ _دعایى که براى دفع چشم زخم است_ نیز حق است،\n💠وَ السِّحْرُ حَقٌّ\nو سِحر حق است،\n💠وَ الْفَأْلُ حَقٌّ\nو فال نیک زدن نیز حق است؛\n💠وَ الطِّیَرَهُ لَیْسَتْ بِحَقٍّ\nاما فال بد زدن حق نیست،\n💠وَ الْعَدْوَى لَیْسَتْ بِحَقٍّ\nسرایت کردن بیماری حق نیست.\n💠وَ الطِّیبُ نُشْرَهٌ، وَ الْعَسَلُ نُشْرَهٌ، وَ الرُّکُوبُ نُشْرَهٌ، وَ النَّظَرُ إِلَى الْخُضْرَهِ نُشْرَهٌ\nبوى خوش، عسل، سوار شدن بر مرکب و نگاه کردن به سبزه، مایه قوت و نشاط است. \n✅امیرالمومنین در این حکمت تأثیر چهار موضوع از امور غیر عادى را تصدیق و تأثیر دو موضوع خرافى را نفى؛ و چهار چیز را مؤثر در نشاط آدمى مى شمرد. \nدر میان همه جوامع در طول تاریخ تا امروز گاهی بین واقعیت ها و خرافه ها خلط اتفاق می افتد ، این خلط از طرفی راه حقایق را به روی مردم بسته و از طرفی راه شیادان را برای سودجویی باز میکند.\n🔺ابن ابی الحدید در ذیل این حکمت ۶۰ صفحه مطلب دارد که بخشی مربوط به توضیح بخش های مختلف این حکمت است، و بخشی مربوط به خرافات در عرب جاهلی است.\n 👈 انداختن زیور به مارگزیده:\nوَ مِنْ مَذَاهِبِ الْعَرَبِ أَیْضًا تَعْلِیقُ الْحُلِیِّ وَالْجَلَاجِلِ عَلَى اللَّدِیغِ، یَرَوْنَ أَنَّهُ یُفِیقُ بِذَلِکَ\nو از جمله روش‌های عرب در دوران جاهلیت نیز، آویختن زیورها و زنگوله‌ها به شخص مارگزیده بود؛ آنها گمان می‌کردند که او با این کار به هوش می‌آید.\n 👈 کور کردن شتر، برای چشم نخوردن:\nوَمِنْ تَخَیُّلَاتِ الْعَرَبِ وَ مَذَاهِبِهَا أَنَّهُمْ کَانُوا یُفَقِئُونَ عَیْنَ الْفَحْلِ مِنَ الْإِبِلِ إِذَا بَلَغَتْ أَلْفًا، کَأَنَّهُمْ یَدْفَعُونَ الْعَیْنَ عَنْهَا.\nو از جمله پندارها و روش‌های عرب در دوران جاهلیت این بود که هنگامی که شترهایشان به هزار نفر می‌رسید، چشم نرِ شتر را کور می‌کردند، گویی می‌خواستند چشم زخم را از آنها دور کنند.\n 👈دفن کردن شتر، کنار قبر اموات:\nفَأَمَّا مَذْهَبُهُمْ فِی الْبَلِیَّهِ — وَهِیَ نَاقَهٌ تُعْقَلُ عِنْدَ الْقَبْرِ حَتَّى تَمُوتُ — فَمَذْهَبٌ مَشْهُورٌ…\nوَکَانُوا یَزْعُمُونَ أَنَّ مَنْ مَاتَ وَلَمْ یُبْلَ عَلَیْهِ، حُشِرَ مَاشِیًا، وَمَنْ کَانَتْ لَهُ بَلِیَّهٌ، حُشِرَ رَاکِبًا عَلَى بَلِیَّتِهِ.\nاما روش آنان درباره «بلیّه» — که شتری است که نزد قبر بسته می‌شود تا بمیرد — روشی مشهور بود. و «بلیه» به این صورت بود که وقتی فرد بزرگی از آنها می‌مرد، شتر او را «بلا» می‌کردند: گردنش را می‌پیچاندند و سرش را به پشت برمی‌گرداندند، و آن را در گودالی رها می‌کردند که نه به آن غذا می‌دادند و نه آب، تا بمیرد. گاه پس از مرگش آن را می‌سوزاندند، و گاه پوستش را می‌کندند و پوستش را از کاه پر می‌کردند.\nو گمان می‌کردند که هر کس که هنگام مرگ برایش «بلا» انجام نشود، در قیامت پیاده محشور می‌شود، و هر کس که برایش بلا شود، سواره محشور میشود.\n👈 صدای الاغ در آوردن برای دفع جن:\nوَ مِنْ خُرَافَاتِ الْعَرَبِ أَنَّ الرَّجُلَ مِنْهُمْ کَانَ إِذَا أَرَادَ دُخُولَ قَرْیَهٍ فَخَافَ وَبَاءَهَا أَوْ جِنَّهَا، وَقَفَ عَلَى بَابِهَا قَبْلَ أَنْ یَدْخُلَهَا فَنَهَقَ نَهِیقَ الْحِمَارِ.\nو از جمله خرافات عرب دوره جاهلیت این بود که وقتی یکی از آنها می‌خواست به روستایی وارد شود و از بیماری یا جنّ های آن می‌ترسید، پیش از ورود، در ورودی آن می‌ایستاد و مانند الاغ عرعر می‌کرد.\n✍️حضرت در این حکمت در مورد برخی خرافه ها و  حقایق توضیح میدهد تا افراد مرز بین این دو را بدانند، نه دچار خرافه شوند، نه واقعیت ها را انکار کنند.\n💠الْعَیْنُ حَقٌّ\n«چشم زخم» حق است.\n✅چشم زدن  از مسائلی است که بسیارى از مردم به آن عقیده دارند و مى گویند در بعضى از چشمها اثر مرموزى نهفته است که با یک نگاه مخصوص ممکن است طرف را بیمار یا هلاک کند یا به دیوانگی بکشاند. \n⁉️آیا چشم زدن واقعیت دارد؟\nمساله ی چشم زخم از نظر عقلى امر محالى نیست ، چه اینکه بسیارى از دانشمندان امروز معتقدند در بـعـضـى از چـشـمـهـا نـیروى مغناطیسى خاصى نهفته شده که کارائى زیادى دارد.\nدر دنیا انرژی های فراوانی وجود دارد که برخی توسط انسان کشف شده اند و برخی هنوز کشف نشده اند.\nارتباطات رادیویی به عنوان امواج نامرئی، اشعه ایکس به عنوانی قدرتی نامرئی و… در عالم وجود دارند و البته بسیاری از اینها نیز کشف نشده اند؛ پس قدرت داشتن چشم ها نیز امری است که کاملا قابل فهم است.\nاز نظر تجربی نیز بـسـیـار هستند کسانی که با چشم خود افرادى را دیده اند که داراى این نیروى مرموز چشم بوده اند، و افراد یا حیوانات یا اشیائى را از طریق چشم زدن از کار انداخته اند.\nلذا نـه تـنـهـا نـبـایـد اصـرارى در انـکـار ایـن امـور داشـت بـایـد امکان وجود آن را از نظر عقل ، علم و تجربه پذیرفت .\n‌✅چشم زخم در آیات و روایات:\n👈 قرآن کریم میفرماید:\nوَإِنْ یَکَادُ الَّذِینَ کَفَرُوا لَیُزْلِقُونَکَ بِأَبْصَارِهِمْ لَمَّا سَمِعُوا الذِّکْرَ\nو کافران چون قرآن را شنیدند، نزدیک بود تو را با چشمانشان بلغزانند و از پای درآورند.\n✍️لَیُزْلِقُونَکَ به معنى لغزیدن و بر زمین افتادن است و کنایه از هلاکت و نابودى مى باشد.\nمشهورترین تفسیر در آیه ی فوق، بحث چشم زخم است. بسیارى از مفسران گفته اند:\nمنظور این است که دشمنان به هنگامى که آیات با عظمت قرآن را از تو مى شنوند، به قدرى خشمگین و ناراحت مى شوند، و با عداوت به تو نگاه مى کنند که گوئى مى خواهند تو را با چشمهاى خود بر زمین افکنند و نابود کنند!\n👈پـیـامبر صلوات الله علیه و آله وسلم:\nالعینُ حَقٌّ، ولو کانَ شیءٌ سَابَقَ القَدَرَ سَبَقَتْهُ العینُ\nآرى ، مانعى ندارد، اگر چیزى مى توانست بر قضا و قدر پیشى گیرد چشم زدن بود.\n✍️ این حدیث به خوبی نشان میدهد بر خلاف عقیده ی برخی که چشم زخم از قدرت الهی خارج است؛ حتی چشم زخم و سحر نیز ذیل قدرت الهی تعریف میشوند و خداوند در برخی چشم ها یا اشیاء قدرتی قرار داده است و آن قدرت در واقع بخشی از عالم اسباب و مسببات است.\n👈 از عبدالله بن عباس روایت شده است که:\nاسْتَعِیذُوا بِاللَّهِ، فَإِنَّ العَیْنَ حَقٌّ\nبه خدا پناه ببرید، زیرا چشم زخم و تأثیر نظر بد حق است و واقعیت دارد.\n 👈 دعای ۲۳ صحیفه سجادیه:\nوَ أَعِذْنِی وَ ذُرِّیتِی مِنَ الشَّیطَانِ الرَّجِیمِ\nو مرا و فرزندانم را پناه ده از شیطان رانده‌شده،\nوَ مِنْ شَرِّ السَّامَّهِ وَ الْهَامَّهِ\nو از شرّ جانوران زهردار و حیوانات بدون زهر\nو الْعَامَّهِ\nو سایر جانداران\nوَ اللَّامَّهِ\nو مردم چشم شور (عین اللّامه=چشم شور)\nوَ مِنْ شَرِّ کلِّ شَیطَانٍ مَرِیدٍ\nو از شرّ هر شیطان سرکش،\nوَ مِنْ شَرِّ کلِّ سُلْطَانٍ عَنِیدٍ\nو از شرّ هر پادشاه ستمگر.\n👈 قرآن کریم در سوره ی یوسف میفرماید:\nوَقَالَ یَا بَنِیَّ لَا تَدْخُلُوا مِنْ بَابٍ وَاحِدٍ وَادْخُلُوا مِنْ أَبْوَابٍ مُتَفَرِّقَهٍ وَمَا أُغْنِی عَنْکُمْ مِنَ اللَّهِ مِنْ شَیْءٍ إِنِ الْحُکْمُ إِلَّا لِلَّهِ عَلَیْهِ تَوَکَّلْتُ وَعَلَیْهِ فَلْیَتَوَکَّلِ الْمُتَوَکِّلُونَ\nو یعقوب گفت: ای پسرانم! از یک در وارد نشوید بلکه از درهای متعدد وارد شوید، و البته من با این تدبیر نمی توانم هیچ حادثه ای را که از سوی خدا برای شما رقم خورده از شما برطرف کنم، حکم فقط ویژه خداست، تنها بر او توکل کرده ام، و همه توکل کنندگان باید به خدا توکل کنند.\n✍️ مشهور مفسران بر این اعتقادند که علت دستور حضرت یعقوب این بود که برادران یوسف، هم از نظر تعداد هم از نظر زیبایی جلب توجه می‌کرند، و پدرشان نگران بود که از این راه چشم زخمى به آنها نرسد. \n👈پیامبر صلوات الله علیه میفرمایند:\nانَّ العَینَ لَتَدخُلَ الرَّجُلَ القَبرَ وَ الجَمَلَ القِدرَ\nچشم زخم؛ انسان صحیح و سالم را داخل قبر می کند و شتر را به دیگ می فرستد.\n👈پیامبر صلوات الله علیه وآله و سلم:\nأَنَّ الْعَیْنَ حَقٌّ تَسْتَنْزِلُ الْحَالِقَ\nچشم‌زخم حق است و قله کوه را در هم میشکند.\n👈علامه مجلسی در بحارالانوار بعد از بیان روایت در جمع بندی میفرماید:\nوَ بِالْجُمْلَهِ لَا یُمْکِنُ إِنْکَارُ ذَلِکَ رَأْسًا لِمَا یُشَاهَدُ مِنْ ذَلِکَ عَیْنًا وَ وُرُودُ الْأَخْبَارِ بِهِ مُسْتَفِیضًا\nو به طور خلاصه، به هیچ وجه نمی‌توان چشم زخم را انکار کرد، زیرا هم به صورت عینی مشاهده می‌شود و هم اخبار فراوانی درباره آن وارد شده است (اخبار مستفیضه یعنی اخبار پر تکراری که به حد تواتر نرسیده باشند)\n‌✅عوامل چشم زدن:\n1⃣حسادت:\nعلامه طباطبائی در تفسیرالمیزان در ذیل آیه ۵ سوره فلق «وَ مِنْ شَرِّ حاسِدٍ إِذا حَسَدَ» می نویسند:\n چشم زدن ناشی از نوعی حسد درونی است.\nشخص حسود وقتی چیزی را ببیند که در نظرش بسیار شگفت آور و بسیار زیبا باشد، حسدش تحریک شده، با همان نگاه، زهر خود را می ریزد.\n2⃣ دوست داشتن:\nپیامبر صلوات الله علیه:\nاِذا رَآى اَحَدُکُمْ مِنْ نَفْسِهِ اَوْ مالِهِ اَوْ مِنْ اَخیهِ ما یُعْجِبُهُ فَلْیَدْعُ لَهُ بِالْبَرَکَهِ فَاِنَّ الْعَیْنَ حَقٌ\nهرگاه یکى از شما در خودش، یا مالش، یا برادرش، چیز جالب توجهى دید، براى برکت یافتن آن دعا کند؛ زیرا چشم زخم، واقعیت دارد.\n✍️ طبق این حدیث چه بسا انسان به خودش و عزیزانش چشم زخم بزند.\nنوعا این نوع چشم زخم از روی حسادت نیست (چون معنای حسادت طبق زوال نعمت است)؛ این چشم زخم از دوست داشتن است.\n 3⃣ بی اختیار:\nکسی که دیگری را چشم می زند به اراده خود، این را کار را نکند، بلکه اثر چشم او کار خودش را می کند.\n✍️ گاهی افرادی نمیدانند چشم شور دارند، یا میدانند ولی ناخواسته چشم میزنند؛ در این موارد گناهی بر آنها نیست.\n❇️گاهی کوچکترین نعمت ها مورد چشم زخم واقع میشود:\nدر دعای حجامت داریم:\nإِذَا أَرَدْتَ اَلْحِجَامَهَ وَ خَرَجَ اَلدَّمُ مِنْ مَحَاجِمِکَ فَقُلْ قَبْلَ أَنْ تَفْرُغَ وَ اَلدَّمُ یَسِیلُ\nهرگاه اراده ی حجامت کردى و خون از محل حجامت خارج شد،قبل از به پایان رسیدن حجامت و جریان خون بگو:\nبِسْمِ اَللّٰهِ اَلرَّحْمٰنِ اَلرَّحِیمِ  أَعُوذُ بِاللَّهِ اَلْکَرِیمِ فِی حِجَامَتِی هَذِهِ مِنَ اَلْعَیْنِ فِی اَلدَّمِ وَ مِنْ کُلِّ سُوءٍ\nدر این حجامت خود،از چشم بد به خون و از هر بدى به خدا پناه مى‌برم.\n✍️ گاهی انسان حجامت میکند و خونی از بدنش خارج میشود، یا این خون رنگ روشنی دارد، یا مقدارش زیاد است و دیگران را به حسادت و چشم زخم میکشاند.\n نکته مهم این است که انسان به هیچ وجه نباید سوء ظن داشته باشد و لی در عین حال تلاش کنیم تا به وسیله ادعیه عمل به روایات خود را از چشم بد مصون بداریم.\n💠الْعَیْنُ حَقٌّ\n💠 وَ الرُّقَى حَقٌّ\nو تعویذ _دعایى که براى دفع چشم زخم است_ نیز حق است.\n🔹رُقَی جمع رُقْیَه به معنای:\nآن چیزی است که به سبب آن میشود بدی ها را دفع کرد.\n ✳️ از آنجایی که حضرت چشم زخم را حق میداند، راهکاری را نیز برای در امان ماندن و درمان آن بیان میفرماید.\nپناه بردن به اذکار و نوشته هایی که در آن ادعیه باشد، راهکاری است که حضرت برای درمان چشم زخم ارائه میدهند.\n🔺 در روایت داریم: \nأَنَّ جَبْرَئِیلَ نَزَلَ عَلَى اَلنَّبِیِّ صَلَّى اَللَّهُ عَلَیْهِ وَ آلِهِ فَرَآهُ مُغْتَمّاً فَسَأَلَهُ عَنْ غَمِّهِ\nروزی جبرئیل بر پیامبر نازل شد و حضرت را غمگین و اندوهگین مشاهده کرد، وقتی علت آن را سؤال کرد\nفَقَالَ لَهُ إِنَّ اَلْحَسَنَیْنِ أَصَابَتْهُمَا عَیْنٌ\nپیامبر فرمودند: ناراحتی ام به خاطر آن است که امام حسن و امام حسین را چشم زده اند.\nفَقَالَ لَهُ یَا مُحَمَّدُ اَلْعَیْنُ حَقٌّ فَعَوِّذْهُمَا بِهَذِهِ اَلْعُوذَهِ\nجبرائیل عرض کرد: ای محمّد چشم زخم واقعیت دارد، پس آن دو را با این جملات تعویذ فرما.\n اَللَّهُمَّ یَا ذَا اَلسُّلْطَانِ اَلْعَظِیمِ وَ اَلْمَنِّ اَلْقَدِیمِ وَ اَلْوَجْهِ اَلْکَرِیمِ ذَا اَلْکَلِمَاتِ اَلتَّامَّاتِ وَ اَلدَّعَوَاتِ اَلْمُسْتَجَابَاتِ عَافِ اَلْحَسَنَ وَ اَلْحُسَیْنَ مِنْ أَنْفُسِ اَلْجِنِّ وَ أَعْیُنِ اَلْإِنْسِ\n  🔺صفوان جمال از امام صادق علیه‌السلام روایت نقل میکند:\nلَوْ نَبَشَ لَکُمْ مِنَ اَلْقُبُورِ لَرَأَیْتُمْ أَنَّ أَکْثَرَ مَوْتَاکُمْ بِالْعَیْنِ لِأَنَّ اَلْعَیْنَ حَقٌّ\nاگر قبرها را بشکافند براى شما، البته بنگرید که بیشتر مرده‌هاى شما براى چشم زدن مرده اند زیرا اثر چشم درست است.\nإِلاَّ أَنَّ رَسُولَ اَللَّهِ صَلَّى اَللَّهُ عَلَیْهِ وَ آلِهِ قَالَ اَلْعَیْنُ حَقٌّ فَمَنْ أَعْجَبَهُ مِنْ أَخِیهِ شَیْءٌ فَلْیَذْکُرِ اَللَّهَ فِی ذَلِکَ فَإِنَّهُ إِذَا ذَکَرَ اَللَّهَ لَمْ یَضُرِّهُ .\nبدان که رسول خدا صلّى اللّٰه علیه و آله فرمود:چشم اثر دارد و هر که خوشش آید از چیزى که برادرش دارد باید در باره آن خدا را به یاد بیآورد،که با یاد خدا زیانى به او نرساند.\n✅ برای بچه های دعای چشم زخم بنویسید:\n  دَخَلَ رَسُولُ اللَّهِ ص بَیْتَ أُمِّ سَلَمَهَ وَ عِنْدَهَا صَبِیٌّ یَشْتَکِی\nرسول خدا به خانه ام سلمه وارد شدند، در نزد او پسر بچه ای بود که ناله می کرد.\nفَقَالَتْ‏ یَا رَسُولَ اللَّهِ أَصَابَتْهُ الْعَیْن\nام سلمه گفت یا رسول اللَّه او را چشم زده اند.\nفَقَالَ ص أَ مَا تَسْتَرْقُونَ لَهُ مِنَ الْعَیْن‏\nایشان فرمود: مگر دعای چشم زخم برایش نگرفتید؟\n❇️اذکار و ادعیه برای دفع چشم زخم:\n📚علامه مجلسی در جلد ۶۰ بحار بابی دارد تحت عنوان “تَأثیرُ السِّحر وَ العَین و حَقیِقَتهما”\nو در جلد ۹۲ بابی دارد تحت عنوان “الدُعاء لِدَفِعِ السِّحرِ وَ العَین‏”\nکه به طور مفصل به نقل روایات، نقل نظر بزرگان و جمع بندی و تحلیل خودش پرداخته است.\n👈 أَنَّ جَبْرَئِیلَ ع رَقَى رَسُولَ اللَّهِ ص وَ عَلَّمَهُ الرُّقْیَهَ وَ هِیَ بِسْمِ اللَّهِ أَرْقِیکَ مِنْ کُلِّ عَیْنِ حَاسِدٍ، اللَّهُ یَشْفِیکَ\nجبرئیل علیه السلام رسول خدا را از چشم زخم حفظ کرد و دعای آن را به ایشان یاد داد و آن دعا این است: « به نام خدا تو را از شر هر چشم حسد ورزنده ای حفظ می کنم، خدا تو را شفا دهد ».\n 👈 این ذکر را بگویید تا کسی را چشم نکنید:\nپیامبر صلوات الله علیه وآله وسلم: مَنْ رَأَى شَیْئاً یُعْجِبُهُ فَقَالَ اللَّهُ الصَّمَدُ مَا شَاءَ اللَّهُ لَا قُوَّهَ إِلَّا بِاللَّهِ لَمْ یَضُرَّ شَیْئاً\nهر کس چیزی ببیند که از آن حوشش بیاید و بگوید: « خدا بی نیاز است، هرچه خدا بخواهد، هیچ نیروئی موجود نیست جز با نیروی خدا» ضرری به آن نمی رساند.\n 🔺همچنین در روایت دیگری از پیامبر صلی الله علیه وآله وسلم:\nإِذَا نَظَرَ أَحَدُکُمْ إِلَى إِنْسَانٍ أَوْ دَابَّهٍ أَوْ إِلَى شَیْ‏ءٍ حَسَنٍ فَأَعْجَبَهُ فَلْیَقُلْ\nهر گاه نگاهتان به انسان یا حیوانی افتاد و از آن شگفت زده شدید، این دعا را بگویید.\nآمَنْتُ بِاللَّهِ وَ صَلَّى اللَّهُ عَلَى مُحَمَّدٍ وَ آلِهِ فَإِنَّهُ لَا یَضُرُّهُ عَیْنُهُ    \n‌👈سوره ی ناس و فلق\n👈دعای حرز کبیر امام جواد:\n اللَّهُمَّ یَا رَبِّ الْأَسْوَاءَ کُلَّهَا وَ اقْمَعْ عَنْهُ أَبْصَارَ الظَّالِمِینَ وَ أَلْسِنَهَ الْمُعَانِدِینَ\nای خدا! او را از همه ی بدیها باز دار و دیده ی ستمگران و زبان دشمنان و کسانی که قصد بدی و ضرر زدن به وی را دارند، از او منصرف گردان.\n ✅ دست هایت را جلوی صورت بگیرد و این دعا را بخوان:\n🔺شخص از امام رضا علیه‌السلام پرسید:\nسَأَلَهُ رَجُلٌ عَنِ الْعَیْنِ فَقَالَ هُوَ حَقٌّ \nامام رضا علیه السلام به مردی که از چشم زخم پرسیده بود، فرمود: چشم زخم حق است.\nفَإِذَا أَصَابَکَ ذَلِکَ فَارْفَعْ کَفَّیْکَ بِحِذَاءِ وَجْهِکَ وَ اقْرَأِ الْحَمْدُ لِلَّهِ وَ قُلْ هُوَ اللَّهُ وَ الْمُعَوِّذَتَیْنِ وَ امْسَحْهُمَا عَلَى نَوَاصِیکَ فَإِنَّهُ نَافِعٌ بِإِذْنِ اللَّهِ\nاگر چشم خوردی دستهایت را در مقابل صورتت بگیر و بر آن سوره حمد و توحید و معوذتین را بخوان و دستت را به صورتت بکش که این کار به اذن خدا نافع است.\n✅نکته اول:\nحرزها، جای خدا را نگیرند:\nدر برخی از روایات از نوشته ها و حرزها نهی شده است و شاید دلیل آن این باشد که انسان فراموش نکند همه کاره ی عالم خداست و بدون اذن او برگی از درختی نمی افتد.\n🔺جابر بن عبدالله انصاری:\nنَهَى رَسُولُ اللَّهِ ص عَنِ الرُّقَى\nرسول خدا(ص) از ورد نهی کرد.\n🔺پیامبرصلوات الله علیه:\nإِنَّ لِلَّهِ عِبَاداً لَا یَکْتَوُونَ وَ لَا یَسْتَرْقُونَ وَ عَلى‏ رَبِّهِمْ یَتَوَکَّلُونَ\nخدا بندگانی دارد که نه برای درمان داغ می کنند و نه ورد می جویند و بر پروردگار خود توکل می کنند.\n✍️توجه به این نکته ضروری است که همه کاره عالم خداوند است ، مبادا با استفاده از حرز و ادعیه وجود خدا را منکر شویم و همه قدرت و توانایی را در آن حرز ببینیم. \n✅نکته دوم:\nپیش هر دعا نویسی نرویم:\n🔺پیامبر صلوات الله علیه وآله وسلم: \nأَنَّهُ نَهَى عَنِ الرُّقَى بِغَیْرِ کِتَابِ اللَّهِ عَزَّ وَ جَلَّ وَ مَا یُعْرَفُ مِنْ ذِکْرِهِ\nپیامبر نهی فرمود از خواندن حرزهایی جز قرآن و نامهاى معروف خدا باشند.\n✍️ برای حرز، انسان باید پیش کسی برود که متدین باشد و از نوشتن مسائل دیگر در حرز خودداری کند. چرا که ممکن است در حرز چیزهایی گنجانده شود که شما را تسخیر خودش کند یا ….\n‌💠الْعَیْنُ حَقٌّ،\n💠وَ الرُّقَى حَقٌّ ،\n💠وَ السِّحْرُ حَقٌّ\nو سِحر حق است.\n✅سحر یا جادو در اصل به معناى هر کارى است که مأخذ آن پنهان باشد.\nحقیقت سحر آن است که چیزى به صورت خارق العاده انجام شود که عوامل متعددى مى تواند داشته باشد.\nگاه صرفاً جنبه چشم بندى و تردستى دارد، گاه از عوامل تلقینى و وهمی ناشى مى شود و گاه از خواص ناشناخته فیزیکى و شیمیایى بعضى از اجسام. گاه به کار گیری اجنه است، گاه استفاده از تاثیرات نجومی است و…\nنوع دیگرى از سحر نیز وجود دارد که ساحر به وسیله ریاضت هاى شدید، اراده خود را چنان تقویت مى کند که مى تواند آثار خارق العاده اى از خود نشان دهد که جنبه چشم بندى ندارد و واقعیت است.\n ❇️وجود داشتن سحر، امری غیر قابل کتمان است:\nدر آیات فراوانى از قرآن مجید اشاره به مسأله سحر شده به خصوص در داستان موسى و فرعون، کراراً از سحر ساحران سخن به میان آمده است و تأثیر آن اجمالاً مورد تأیید واقع شده که از طریق معجزه موسى سحر آن ها باطل شد.\n 🔺قرآن کریم در ایه ۱۱۶ اعراف در مورد ساحران فرعون میفرماید:\nسَحَرُوا أَعْیُنَ النَّاسِ وَاسْتَرْهَبُوهُمْ وَجَاءُو بِسِحْر عَظِیم\nمردم را چشم بندى کردند و ترساندند، و سحر عظیمى پدید آوردند.\n🔺همچنین در آیه ۶۶ سوره طه مى فرماید:\nفَإِذَا حِبَالُهُمْ وَ عِصِیُّهُمْ یُخَیَّلُ إِلَیْهِ مِنْ سِحْرِهِمْ أَنَّهَا تَسْعَى\nدر این هنگام طناب ها و عصاهاى آنان براثر سحرشان چنان به نظر مى رسید که حرکت مى کنند!\n🔺قرآن کریم در آیه ۱۰۲ سوره بقره در مورد ابطال سحر سخن میگوید:\nوَ مَا اُنزِلَ عَلی الْمَلَکینْ بِبَابِلَ هَارُوتَ وَ مَارُوت\nآنچه بر دو فرشته هاروت و ماروت در شهر بابل نازل شد.\n✍️ در دوره حضرت سلیمان  گروهی به سحر و جادوگری پرداختند، ایشان دستور داد تمام نوشته‌های آنها را جمع‌آوری و در محلی نگهداری کنند. پس از وفات سلیمان گروهی نوشته‌ها را یافتند و به یادگیری سحر مشغول شدند.\nدر سرزمین بابل سحر و جادوگری به اوج خود رسید و باعث ناراحتی و اذیت مردم شد، خداوند دو فرشته را به صورت انسان مأمور ساخت که عوامل سحر و طریق ابطال آن را به مردم بیاموزند، تا بتوانند خود را از شر ساحران بر کنار دارند. هر چند مردم از این علوم در مسیر باطل استفاده کردند.\n ❎استفاده از سحر برای به طلاق کشیدن کار زن و شوهرها:\n🔺قرآن کریم بعد از بیان جریان هاروت و ماروت میفرماید:\nفَیَتَعَلَّمُونَ مِنْهُمَا مَا یُفَرِّقُونَ بِهِ بَیْنَ الْمَرْءِ وَزَوْجِهِ\nولى مردم از آن دو فرشته، مطالبى را مى آموختند که بتوانند به وسیله آن، میان مرد و همسرش جدایى بیفکنند.\n✍️توجه به این نکته ضروری است که بروز هر اختلافی در خانواده، آن را به سحر و جادو ربط ندهیم ولی گوشه ذهنتان باشد که شاید به واسطه سحر و جادو اتفاق افتاده باشد و فقط در حد شاید به آن توجه کنیم ، نه بیشتر.\n❎ سحر پیامبر اسلام توسط یهودیان مدینه:\n🔺در منابع روایی به جریان سحر کردن پیامبر اشاره شده است.\nإِنَّ فُلَاناً الْیَهُودِیَّ سَحَرَکَ وَ جَعَلَ السِّحْرَ فِی بِئْرِ بَنِی فُلَانٍ\nفلان مرد یهودی پیامبر را سحر کرد و سحر را در چاهی قرار داد.\n📚 مرحوم سید جعفر مرتضی عاملی در جلد ۱۶ کتاب” الصحیح من سیره النبی الأعظم” به بررسی این ماجرا پرداخته است:\nدر سال ششم یا هفتم هجری قمری، پیامبر اسلام  توسط یهودیان مدینه مورد سحر قرار گرفتند. این واقعه که به مدت ۴۰ روز، ۶ ماه یا حتی یک سال به طول انجامید، تأثیرات قابل توجهی بر سلامت ایشان گذاشت.\nاین سحر توسط یکی از عوامل یهود در زیر سنگ چاهی در مدینه پنهان کرد.\nبرخی منابع نیز اشاره می‌کنند که غلامی از یهودیان که در خدمت پیامبر بود، توسط یهودیان تحریک شد تا موهای پیامبر و شانه‌ای که ایشان از آن استفاده می‌کردند را به دست آورده و در اختیار یهودیان قرار دهد. این اشیاء سپس برای سحر مورد استفاده قرار گرفتند.\nسحر انجام شده بر پیامبر اسلام  تأثیرات جسمی و روانی قابل توجهی داشت.\nدر نهایت، دو فرشته به نزد پیامبر  آمدند و محل پنهان شدن سحر را به ایشان اطلاع دادند. این سحر در زیر سنگ چاهی در مدینه پنهان شده بود و آب چاه به دلیل شدت سحر زرد شده بود. پس از کشف سحر، پیامبر  دستور دادند تا آن را از چاه خارج کنند و با خواندن آیاتی از قرآن، اثر سحر از بین رفت.\nدر روایت است که پیامبر بعد از ابطال سحر فرمود:\nکَأَنَّمَا اُنْشِطَ مِنْ عِقَالٍ\nمثل اینکه از بند آزاد شدم.\n❇️سحر کردن شخصی توسط حاکم حبشه:\nعلی بن ابراهیم قمی در تفسیرش میگوید وقتی مسلمانان به حبشه رفتند، قریش دو نفر را برای بازگرداندن آنها نزد پادشاه حبشه فرستاد. یکی از آن دو عمروعاص بود و یکی عُمَارَهَ بْنَ اَلْوَلِیدِ\nعماره بن ولید خطای بزرگی مرتکب شد (ارتباط با یکی از کنیزان پادشاه)؛ پادشاه میخواست عماره را بکشد ولی چون مهمان بود از این کار صرف نظر کرد؛\n فَدَعَا السَّحَرَهَ فَقَالَ لَهُمْ اعْمَلُوا بِهِ شَیْئاً أَشَدَّ عَلَیْهِ مِنَ الْقَتْلِ\nاو را سحر کنید به نحوی که از مرگ بدتر باشد.\nفَصَارَ مَعَ الْوَحْشِ یَغْدُو وَ یَرُوحُ وَ کَانَ لَا یَأْنَسُ بِالنَّاسِ … حَتَّى مَاتَ الْخَبَر\nاو بعد از سحر خوی وحشى‌گری پیدا کرد و به همراه وحوش شب و روز به سر میبرد و از مردم دور میشد؛  و اینگونه بود تا مُرد.\n✅انواع سحر در کلام امام صادق علیه السلام:\nسَأَلَ الزِّنْدِیقُ أَبَا عَبْدِ اللَّهِ ع فِیمَا سَأَلَهُ فَقَالَ أَخْبِرْنِی عَنِ السِّحْرِ مَا أَصْلُهُ\nزندیقی از امام صادق علیه السلام در ضمن پرسش هایش سوال کرد و گفت: به من بگو اصل سحر چیست؟\nوَ کَیْفَ یَقْدِرُ السَّاحِرُ عَلَى مَا یُوصَفُ مِنْ عَجَائِبِهِ وَ مَا یَفْعَل\nچگونه ساحر می تواند آنچه از عجایب سحر گفته می شود را انجام دهد و ساحر چه می کند؟\nقَالَ إِنَّ السِّحْرَ عَلَى وُجُوهٍ شَتَّى: وَجْهٌ مِنْهَا بِمَنْزِلَهِ الطِّبِّ کَمَا أَنَّ الْأَطِبَّاءَ وَضَعُوا لِکُلِّ دَاءٍ دَوَاءً فَکَذَلِکَ عِلْمُ السِّحْرِ احْتَالُوا لِکُلِّ صِحَّهٍ آفَهً وَ لِکُلِّ عَافِیَهٍ عَاهَهً وَ لِکُلِّ مَعْنًى حِیلَهً\nفرمود: سحر اقسام مختلفی دارد: یک قسم از آن مانند پزشکی است. همان گونه که پزشکان برای هر دردی دوائی قرار داده اند علم سحر هم همان گونه است. ساحران برای هر سلامتی مرضی پیدا کرده اند، و برای هر عافیتی یک آفت و برای هر معنایی یک نیرنگ.\n✍️ استفاده از خواص گیاهان و سنگ ها و فلزات و ادعیه و…\n وَ نَوْعٌ مِنْهُ آخَرُ خَطْفَهٌ وَ سُرْعَهٌ وَ مَخَارِیقُ وَ خِفَّهٌ\nقسم دیگری از آن یک چشم بندی و سرعت در کار و نیرنگ و تردستی است.\n✍️ این نوع از سحر همان چشم بندی معروف است که امروزه به شعبده بازی شناخته میشود\n وَ نَوْعٌ مِنْهُ مَا یَأْخُذُ أَوْلِیَاءُ الشَّیَاطِینِ عَنْهُمْ…\nقسمی از آن چیزهایی است که نزدیکان به شیاطین از آن ها می گیرند.\n✍️ این بخش که مهمترین بخش سحر و جادو است، استفاده از اجنه و موکل گرفتن است.\n 👈خرافات در مورد سحر:\nدر ادامه  همین رواییت داریم:\nقَالَ أَ فَیَقْدِرُ السَّاحِرُ أَنْ یَجْعَلَ الْإِنْسَانَ بِسِحْرِهِ فِی صُورَهِ الْکَلْبِ أَوْ الْحِمَارِ أَوْ غَیْرِ ذَلِکَ\nزندیق گفت: آیا ساحر با سحرش می تواند انسان را به شکل سگ یا الاغ یا غیر آن در آورد؟\nقَالَ هُوَ أَعْجَزُ مِنْ ذَلِکَ وَ أَضْعَفُ مِنْ أَنْ یُغَیِّرَ خَلْقَ اللَّهِ\nفرمود: او توانایی آن کار را ندارد و ضعیف تر از آن است که آفرینش خدا را دگرگون سازد!\n👈بخشی از سحر به خاطر دهن لقی هاست:\nدر ادامه  همین رواییت داریم:\nوَ إِنَّ مِنْ أَکْبَرِ السِّحْرِ النَّمِیمَهَ\nو به راستی یک از بزرگ ترین سحرها سخن چینی است!\nیُفَرَّقُ بِهَا بَیْنَ الْمُتَحَابَّیْنِ وَ یُجْلَبُ الْعَدَاوَهُ عَلَى الْمُتَصَافِیَیْنِ وَ یُسْفَکُ بِهَا الدِّمَاءُ وَ یُهْدَمُ بِهَا الدُّورُ وَ یُکْشَفُ بِهَا السُّتُور\nبا آن بین دو دوست جدایی افکنده می شود و بین یاران صمیمی دشمنی ایجاد می شود، با آن خون ها ریخته می شود و خانه ها ویران می شود و پرده ها دریده می شود.\n✍️هم سخن چینی توسط دیگران موجب کینه و دشمنی میشود و اثری همچون سحر دارد و هم بیان اسرار زندگی برای دیگران میتواند اطلاعات کافی برای سحر را در اختیار دیگران بگذارد\nپس باید از غیبت و بد گویی نزد دیگران خود داری کرد و هم به حفظ اسرار پرداخت.\n✅ادعیه و حرزهای ابطال سحر:\n🔺راوی میگوید:\nسَأَلْتُ اَلرِّضَا عَلَیْهِ السَّلاَمُ عَنِ اَلسِّحْرِ فَقَالَ هُوَ حَقٌّ وَ هُوَ یُضِرُّ بِإِذْنِ اَللَّهِ تَعَالَى\nاحمد بن عیسى گوید از حضرت رضا در بارۀ سحر پرس و جو کردم فرمود:سحر واقعیت دارد و باذن خدا اثر و ضرر مى‌کند\nفَإِذَا أَصَابَکَ ذَلِکَ فَارْفَعْ یَدَکَ حِذَاءَ وَجْهِکَ وَ اِقْرَأْ عَلَیْهَا\nو چون تو را سحر کردند دستت را تا مقابل صورتت بالا ببر و بخوان\n بِسْمِ اَللَّهِ اَلْعَظِیمِ بِسْمِ اَللَّهِ اَلْعَظِیمِ رَبِّ اَلْعَرْشِ اَلْعَظِیمِ إِلاَّ ذَهَبَتْ وَ اِنْقَرَضَتْ\n  🔺مرحوم شیخ عباس قمی در حاشیه کتاب مفاتیح الجنان می گوید:\nجهت باز کردن بسته شده، آیات زیر بر کاغذ نوشته شود، و بر او آویزان گردد.\n1⃣سوره فتح، آیه ۱و۲\n2⃣سوره نصر\n3⃣سوره روم، آیه ۲۱:\n«وَ مِنْ ءَایَاتِهِ أَنْ خَلَقَ لَکُم مِّنْ أَنفُسِکُمْ أَزْوَاجًا لِّتَسْکُنُواْ إِلَیْهَا وَجَعَلَ بَیْنَکُم مَّوَدَّهً وَ رَحْمَهً إِنَّ فِی ذَلِکَ لاَیَت لِّقَوْم یتَفَکَّرُونَ»\n4⃣سوره مائده، آیه ۲۳\n«ادْخُلُواْ عَلَیْهِمُ الْبَابَ فَإِذَا دَخَلْتُمُوهُ فَإِنَّکُمْ غَالِبُونَ»\n5⃣سوره قمر، آیه ۱۲-۱۱ :\n«فَفَتَحْنَآ أَبْوَابَ السَّمَآءِ بِمَآء مُّنْهَمِر * وَ فَجَّرْنَا الاْرْضَ عُیُونًا فَالْتَقَی الْمَآءُ عَلَی أَمْر قَدْ قُدِرَ»\n6⃣سوره طه، آیه ۲۸-۲۵:\n«قَالَ رَبِّ اشْرَحْ لِی صَدْرِی * وَ یَسِّرْ لِی أَمْرِی * وَاحْلُلْ عُقْدَهً مِّن لِّسَانِی * یَفْقَهُواْ قَوْلِی »\n 7⃣ سوره کهف، آیه ۹۹:\n«وَ تَرَکْنَا بَعْضَهُمْ یَوْمَئِذ یَمُوجُ فِی بَعْض وَ نُفِخَ فِی الصُّورِ فَجَمَعْنَاهُمْ جَمْعًا»\n8⃣ سوره توبه، آیه ۱۲۹-۱۲۸:\n«لَقَدْ جَآءَکُمْ رَسُولٌ مِّنْ أَنفُسِکُمْ عَزِیزٌ عَلَیْهِ مَا عَنِتُّمْ حَرِیصٌ عَلَیْکُم بِالْمُؤْمِنِینَ رَءُوفٌ رَّحِیمٌ * فَإِن تَوَلَّوْاْ فَقُلْ حَسْبِی اللَّهُ لاَ إِلَهَ إِلاَّ هُوَ عَلَیْهِ تَوَکَّلْتُ وَ هُوَ رَبُّ الْعَرْشِ الْعَظِیمِ». \n✅نکته اول:\nگناه ساحر بخشیده شدنی نیست:\nدر بخش چشم زخم بیان شد که برخی از چشم زخم ها، گناهی ندارند چون خود شخص در آن تاثیری ندارد. ولی سحر چون امری ارادی است که شخص برای آن تلاش میکند؛ حتما گناه دارد.\n🔺 پیامبر صلوات الله علیه وآله وسلم:\nثَلَاثَهٌ لَا یَدْخُلُونَ الْجَنَّهَ مُدْمِنُ خَمْرٍ وَ مُدْمِنُ سِحْرٍ وَ قَاطِعُ رَحِم‌\nسه طایفه وارد بهشت نمی‌شوند؛ دائم الخمر ، کسی که شغلش ساحری است و کسی که قطع رحم کرده باشد.\n ✅نکته دوم:\nسِحر هر چه هم بزرگ باشد، به قدرت خدا نمیرسد:\nامیرالمومنین در این حکمت به حق بودن سحر اشاره فرموده است، ولی هیچ بحثی در مورد میزان تاثیر سحر بر زندگی بیان نفرموده است. آنچه مهم است آن است که سحر و ساحر نمیتواند بر قدرت الهی فائق بیایند، اگر انسان اهل رعایت حلال و حرام، نجاست و پاکی باشد، اهل نماز باشد، اهل صدقه و دعا باشد؛ یا سحر به او آسیب نمیزند یا آسیب ها او را از پا در نمی آورد.\n🔺در یکی از ادعیه امام سجاد علیه‌السلام داریم:\nفَاحْفَظْنِی بِحِفْظِ الْإِیمَانِ مِنْ بَیْنِ یَدَیَّ وَ مِنْ خَلْفِی وَ عَنْ یَمِینِی وَ عَنْ شِمَالِی وَ مِنْ فَوْقِی وَ مِنْ تَحْتِی‏\nپس مرا حفظ فرماى به حفظ ایمان از جلو و دنبال سر و از راست و از چپ من و از بالاى سر من و از زیر پایم.\nوَ ادْفَعْ عَنِّی بِحَوْلِکَ وَ قُوَّتِکَ فَإِنَّهُ لاَ حَوْلَ وَ لاَ قُوَّهَ إِلاَّ بِاللَّهِ الْعَلِیِّ الْعَظِیمِ‏\nو دفع کن از من به قدرت و حول خود بدرستى که هیچ جنبش و توانى نیست مگر به خداوند بلند مرتبه بزرگ مقام.\n✍️ ما وظیفه خود را انجام دهیم، دچار افراط و تفریط نشویم؛ خداوند حافظ و نگهبان ما خواهد بود.\nغفر الله لی و لکم الحمدلله رب العالمین","بخش دوم\nمتن:\nوَ قَالَ (عليه السلام): الْعَيْنُ حَقٌّ، وَ الرُّقَى حَقٌّ، وَ السِّحْرُ حَقٌّ، وَ الْفَأْلُ حَقٌّ؛ وَ الطِّيَرَةُ لَيْسَتْ بِحَقٍّ\nترجمه:\nامام (عليه السّلام) فرمود: «چشم زخم» حق است و تعويذ (دعايى كه براى دفع چشم زخم است) نيز حق است و سِحر حق است و فال (نيك) نيز حق است اما طيره (فال بد) حق نيست\nتفسیر:\n💠الْعَیْنُ حَقٌّ، وَ الرُّقَى حَقٌّ ، وَ السِّحْرُ حَقٌّ،\n💠وَ الْفَأْلُ حَقٌّ\nو فال نیک زدن نیز حق است.\nتفأّل عبارت است از فال نیک زدن به مکان یا زمان، افراد، اشیاء و …\nاگر چه در زبان فارسی عامیانه امروز، فال به معنای پیشگویی مطرح است،\nولی منظور از فال در ادبیات عرب این است که انسان حادثه اى را نشان پیروزى، موفقیت و پیشامدهاى خیر بداند.\n⏪مثلاً بگوید که چون فلان نوزاد در روز میلاد مبارک یکى از معصومین(علیهم السلام) متولد شده آینده خوبى دارد و یا این که صبحگاهان که از منزل خارج مى شود وقتى با انسان صالح و خوب و درست کارى برخورد کرد بگوید این نشان مى دهد که امروز کارهاى ما روبه راه خواهد بود. عرب از این گونه پیش بینى ها به فال تعبیر مى کند که همان تفأل خوب است.\n❓آیا بین دو اتفاقی که در خارج افتاده رابطه ای هست که به آن فال نیک بزنیم؟!\n❓آیا واقعاً رابطه اى میان این گونه حوادث و حوادث دیگرى که پشت سر آن پیش بینى مى کنند وجود دارد؟\nاز جهت ظاهری هیچ دلیلى براى آن در دست نیست ولى یک نکته را نمى توان انکار کرد و آن این که :\n◀️اولا : وقتى انسان تفأل به خوبى مى زند اثر روانى قابل ملاحظه اى در او دارد; او را امیدوار به آینده خوب مى سازد و اراده او را براى ادامه کارها تقویت مى کند و به او شجاعت و استقامت مى بخشد و این اثر روانى، قابل انکار نیست و اى بسا همان، سبب پیشرفت و پیروزى مى شود.\n◀️ثانیا : از جهت تکوینی خداوند به فال نیک زدن، ترتیب اثر میدهد.\nخدا به عالم دستور داده اگر این انسان فال خیر زد،شما خیر برایش مقدر کنید،فال نیک زد نیکی سر راه او بیاید این اراده خدا است.شما با یک فال نیک زدن میتوانید روز خود را بسازید،می‌توانید عاقبت بخیری یک عمر حیات خوب برای خودتان رقم بزنید.باید عادت کنیم زبانمان به خیر بچرخد.\n✳️شاید عقل به درک چیزی نرسد، ولی شرع آن را ثابت میکند:\n📚 مرحوم علامه طباطبایی در المیزان بحثی دارد :\nایشان در مورد نحس بودن ایام میفرماید:\nوَ لَا سَبِیلَ لَنَا إِلَى إِقَامَهِ الْبُرْهَانِ\nهیچ راهی برای اثبات سعادت یا نحوست یک روز یا زمان خاص نداریم…\nأَمَّا بِحَسَبِ النَّظَرِ الشَّرْعِیِّ فَفِی الْکِتَابِ ذِکْرٌ مِنَ النُّحُوسَهِ\nاین از نظر عقلی است. اما از نظر شرعی، در قرآن ذکری از نحوست و مقابل آن شده است، مانند آیه: ما بر آنان تندبادی سرد در روزی شوم و پیوسته فرستادیم.\n✍️ همین فرمایش علامه در مورد فال نیک زدن نیز هست. شاید ما از جهت عقلی نتوانیم ارتباطی پیدا کنیم بین روبرو شدن با یک مومن  در اول صبح، با اتفاقات خوب در طول روز؛ ولی ادله ی شرعی این مطلب را تایید میکنند.\n🔺 در ماجراى برخورد مسلمانان با کفار مکه در سرزمین حدیبیه؛ هنگامى که سهیل بن عمرو به عنوان نماینده کفار مکه به سراغ مسلمانان آمد و پیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم از نام او آگاه شد به مسلمانان فرمود:\nقد سَهُلَ علیکُم أمرُکُم\nکار بر شما آسان شد.\n✍️ چون نام آن مرد سهیل بود پیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم آن را به فال نیک گرفت.\nشاید انسان درنگاه اول بگوید این چیست؟ اسم یک مشرک سهیل است امر بر ما سهل می‌شود این اراده ی خداست که شما اگر نگاه مثبت اندیشی داشته باشید ،خدا این امر را برشما سهل خواهد کرد.\n📚غرر الحکم:\nتَفَأَّلْ بِالْخَیْرِ تَنْجَحْ\nکار را به فال نیک بگیرید تا پیروز و کامیاب شوید.\n✍️ تفال به خیر زدن در واقع تلقین خوبی و پیرزی است، و تلقین نقش مهمی دارد.\n🔺پیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nإِنَّ اللَّهَ یحِبُّ الْفَأْلَ الْحَسَن\nخداوند فال نیک را دوست دارد.\n❎ به هر چیز خوبی که میشنوید فال خوب بزنید:\nپیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nنِعمَ الشیءُ الفَألُ ؛ الکَلِمَهُ الحَسَنهُ یَسمَعُها أحَدُکُم\nچه خوب چیزى است فال خوب زدن؛ سخن نیکى که فردى از شما آن را مى شنود.\n✳️کاری کنیم، مردم فال نیک به ما بزنند:\nدرحکمت ۲۴۸: \nمَنْ ظَنَّ بِکَ خَیْراً، فَصَدِّقْ ظَنَّهُ:\n✍️بخشی از فال نیک زدن، به صداها و ایام و مکان ها است، ولی بخشی از فال نیک زدن ها به اشخاص است. حضرت میفرماید اگر کسی به شما امیدی داشت، به شما و کمکتان دل بسته بود، او را ناامید نکنید و فال نیک او را تصدیق کنید.\n‌✳️تفال به خیر در سیره پیامبر:\nخود اهل بیت نه تنها دستور دادند بلکه در عمل اجرا کردند.\n📚مرحوم صدوق در امالی نقل میکند در جریان جنگ خندق:\nآنگاه که پیامبر فرمان حفر خندق را داد،سنگ صخره مانندى در پهناى آن هویدا گشت که کلنگ در آن اثر نداشت.\n فَجَاءَ رَسُولُ اللَّهِ صَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nفَلَمَّا رَآهَا وَضَعَ ثَوْبَهُ\nناگزیر رسول اکرم نزدیک آمد و جامه خویش بر زمین گذاشت و کلنگ به دست گرفت و گفت«بسم اللّه»\nوَ ضَرَبَ ضَرْبَهً فَکَسَرَ ثُلُثَهَا وَ قَالَ اللَّهُ أَکْبَرُ أُعْطِیتُ مَفَاتِیحَ الشَّامِ\nناگهان سنگ سخت و بزرگ با یک ضربت یک‌سوم آن ترک خورد.پیامبر فرمود:اللّه اکبر.اکنون کلیدهاى شام را به دست من دادند و سوگند به خداوند که هم‌اکنون قصرهاى سرخ آن سرزمین را مشاهده مى‌کنم.\nثُمَّ ضَرَبَ الثَّانِیَهَ فَقَالَ بِسْمِ اللَّهِ فَفَلَقَ ثُلُثاً آخَرَ فَقَالَ اللَّهُ أَکْبَرُ أُعْطِیتُ مَفَاتِیحَ فَارِسَ\nآنگاه براى بار دوم گفت«بسم اللّه»و یک‌سوم دیگر سنگ جدا شد.فرمود:اللّه اکبر اکنون کلیدهاى فارس را به دست من دادند.سوگند به خداوند که قصرهاى سفید مدائن را مشاهده مى‌کنم\nثُمَّ ضَرَبَ الثَّالِثَهَ فَفَلَقَ بَقِیَّهَ الْحَجَرِ وَ قَالَ اللَّهُ أَکْبَرُ أُعْطِیتُ مَفَاتِیحَ الْیَمَنِ وَ اللَّهِ إِنِّی لَأُبْصِرُ أَبْوَابَ الصَّنْعَاءِ مَکَانِی هَذَا\nپیامبر صلّى اللّه علیه و آله کلنگ را به سنگ زد و یک‌سوم دیگر سنگ شکست و فرمود:اکنون کلیدهاى یمن را به دست من دادند.از اینجا دروازه‌هاى شهر«صنعاء»را مشاهده مى‌کنم.\n✍️ پیامبر این سنگ سخت را به مثابه ی مشکلات سر را پیشرفت اسلام گرفتند که در واقع عنان امپراطوری های بزرگ آن زمان بودند، پیامبر آنها را در هم شکست و دین را به آنجا عرضه کرد.\nخدا دوست دارد ما اهل تفال به خیرباشیم .خدادوست دارد ما همیشه فال نیک بزنیم ،اتفاقا اگرفال نیک زدیم درتکوین عالم و این تلقینی که انسان میکند راه برای او باز می‌شود.\n❇️خسرو پرویز جواب نامه پیامبر را با خاک داد:\n📚مرحوم مجلسی در جلد ۲۰ بحار الانوار نقل میکند:\n أَنَّ اَلنَّبِیَّ کَتَبَ إِلَى کِسْرَى مِنْ مُحَمَّدٍ رَسُولِ اَللَّهِ إِلَى کِسْرَى\n\nپیامبر به خسرو این نامه را نوشت: «از طرف محمد رسول خدا به سوی خسرو پسر هرمز اما بعد اسلام آور تا سالم بمانی و گر نه آماده نبرد با خدا و رسولش باش\n\nفَلَمَّا وَصَلَ إِلَیْهِ اَلْکِتَابُ مَزَّقَهُ وَ اِسْتَخَفَّ بِهِ\nچون نامه به خسرو رسید آن را درید و خوار شمرد و گفت: این کیست که گستاخانه مرا به کیش خود می خواند و نام خود را پیش از نام من مینویسد.\n \nنامه پیامبر صَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم را پاره کرد و مقداری خاک در پاسخ پیامبر فرستاد\nفَقَالَ صَلَّى اللَّهُ عَلَیْهِ وَ آلِهِ مَزَّقَ اَللَّهُ مُلْکَهُ کَمَا مَزَّقَ کِتَابِی\nپیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم\nفرمود: «خدا ملک او را را در هم بشکند چنانچه نامه ام را پاره کرد.\n أَمَا إِنَّهُ سَتُمَزِّقُونَ مُلْکَهُ  \nبه زودی ملک او را در هم خواهید. شکست\n وَ بَعَثَ إِلَیَّ بِتُرَابٍ أَمَا إِنَّکُمْ سَتَمْلِکُونَ أَرْضَهُ  \nو برای من خاک فرستاده حال شماها سرزمین او را مالک خواهید شد.\n فَکَانَ کَمَا قَالَ\nو چنان شد که فرمود.\n✳️سفیران، نام نیکو داشته باشند:\nدر برخی از منابع اهل سنت آمده است:\nکَانَ رَسُولُ اللَّهِ یَکْتُبُ إِلَى أُمَرَائِهِ: إِذَا أَبْرَدْتُمْ إِلَیَّ بَرِیدًا فَأَبْرِدُوهُ حَسَنَ الاسْمِ\nپیامبر صَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nخدا به فرمانداران خود می‌نوشت: هرگاه پیکی به سوی من می‌فرستید، او را خوش‌نام بفرستید.\n✅نکته:\nتفال به قرآن:\nحالا که بحث تفال به خیر است، به یک نکته نیز باید اشاره شود و آن تفال به قرآن است.\nدر برخی از روایات بحث تفال به قرآن مجاز شمرده شده و در برخی از این کار نهی شده است.\n❇️تفال به معنای مشورت و استخاره با قرآن مجاز است:\nدر دعایی که هنگام استخاره خوانده میشود میگوییم:\nاللَّهُمَّ إِنِّی تَفَأَّلْتُ بِکِتَابِکَ وَ تَوَکَّلْتُ عَلَیْکَ فَأَرِنِی مِنْ کِتَابِکَ مَا هُوَ الْمَکْتُومُ مِنْ سِرِّکَ الْمَکْنُونِ فِی غَیْبِک\nخدایا به کتاب تو تفأل می زنم، و بر تو توکل می کنم و از کتابت آنچه را که در نهان غیب تو، پوشیده شده به من بنمایان.\n✳️تفال به معنای فال و طلب پیشگویی از قرآن مجاز نیست:\nدر روایتی از امام صادق علیه السلام داریم: لَا تَتَفَأَّلْ بِالْقُرْآنِ\nتفال به قرآن نکنید.\nاین تفال ،تفال دیگری است به معنای فارسی یعنی (پیش گویی )این خرافات است نهی شده\n✍️ علامه مجلسی می فرماید: معنای این حدیث آن است که از فال گشودن قرآن، برای استنباط احوال آینده از آیات نهی شده است، چنان که برخی از جاهلان، این روش را وسیله ای برای کسب روزی خود قرار داده اند و به این صورت، مردم را فریب می دهند\n💠الْعَیْنُ حَقٌّ وَ الرُّقَى حَقٌّ، وَ السِّحْرُ حَقٌّ، وَ الْفَأْلُ حَقٌّ؛ وَ الطِّیَرَهُ لَیْسَتْ بِحَقٍّ  \nاما فال بد زدن و بد شگونی حق نیست\nحضرت بعد از بیان چهار مورد از مواردی که منشأ نامحسوسی دارند، ولی حق هستند؛ به دو مورد از خرافه‌ها اشاره میفرمایند.\nطِیرَه از ماده‌ی طیر و طائر است، از آنجایی که اعراب جاهلی با دیدن یا شنیدن صدای پرندگان، فال بد میزدند، ابتدا این لفظ برای فال بد به پرندگان بوده ولی آرام‌آرام این لفظ به معنای مطلق فال بد به کار میرود.\n عربها هرگاه قصد سفر می‌کردند به نخستین پرنده‌ای که بر می‌خوردند، آن را رم می‌دادند، اگر به سمت راست می‌پرید به سفر می‌رفتند و آن را مبارک می‌شمردند و هرگاه به سمت چپ می‌پرید از سفر منصرف می‌شدند و آن را شوم می‌دانستند\nبحث بد شگونی نیز در اینجا است، اینکه فلانی وارد خانه شد، ما تصادف کردیم، فلانی طلاق گرفته سر سفره ی عقد ننشیند و…\n✳️فال بد زدن در قرآن:\nدر قرآن مجید نیز به طور مکرر واژه «طیره» در همین معنا به کار رفته که مشرکان خرافى مسلک در برابر پیامبران الهى به این حربه متوسل مى شدند تا روحیه آن ها را تضعیف کنند و یا مردم را از اطراف آن ها پراکنده سازند.\n👈درمورد موسى کلیم و یارانش مى فرماید: یَطَّیَّرُوا بِمُوسَى وَمَنْ مَّعَهُ\nهرگاه ناراحتى به فرعونیان مى رسید آن را به شوم بودن موسى و همراهانش نسبت مى دادند.\n👈در مورد قوم ثمود نیز مى فرماید: قَالُوا اطَّیَّرْنَا بِکَ وَ بِمَنْ مَّعَکَ\nگفتند: ما به تو و کسانى که با تو هستند فال بد مى زنیم و شما را شوم مى دانیم.\nدشمنان همیشه این نسبت را به مومنین و به انبیاء میدادند دشمن از این خرافه ها استفاده میکند تا جریان حق را تضعیف کند مومنین باید هوشیار باشند.\n❇️چرا از فال بد نهى شده است؟:\nبرخی می‌گویند ‌به‌‌ خاطر پریدن فلان حیوان، به خاطر صدای کلاغ و… حتماً حادثه تلخی پیش می‌آید. کف پای کسی میخارد و میگوید الان خبر بد میشنوم. زبانم را گاز گرفتم، دارند پشت سرم حرف میزنند.\nعده ای پرواز پرندگان، حرکت خرگوش، افتادن نمکدان، هدیه دادن چاقو، رد شدن از زیر نردبان، عدد سیزده و امور بی‌شمار دیگری را دلیل بر اتفاقات تلخ میدانند در حالی که:\n1⃣ اولا یک مسأله خرافى است و هیچ گونه رابطه اى در میان پرواز پرندگان، به ویژه کلاغ و حوادث شوم وجود ندارد.\n2⃣ثانیا  فال بد زدن باعث تضعیف روحیه ها و سستى اراده ها مى گردد. و اسلام به هیچ وجه موافق تضعیف روحیه نیست.\n3⃣ثالثا از جهت تکوینی خداوند بین اتفاقات عادی عالم و بد شدن وقایع  بعدی هیچ ارتباطی قرار نداده است.\n✳️تفاوت تفال و تطیر در چیست؟!\nخداوند در تفال اثر تکوینی گذاشته و فال نیک زدن اثر میگذارد ولی در فال بد زدن اثر نگذاشته و اثری ندارد.\n⏪مانند ثواب و گناه؛ خداوند تکوینی ثوابِ عمل خیر را ده برابر قرار داده؛ ولی جزا و عذاب گناه را یکی قرار داده است با اینکه هر دوی اینها انجام دادن یک فعل و عمل است.\n✍️لذا خدا در فال نیک زدن اثر گذاشته ولی در فال بد زدن اثر نگذاشته است.\n\n✳️فال بد زدن نشانه ی جهل است:\nدر آیه ۱۳۱ اعراف میفرماید:\nفَإِذَا جَاءَتْهُمُ الْحَسَنَهُ قَالُوا لَنَا هَٰذِهِ  \nپس هنگامی که رفاه و نعمت به آنان روی می کرد، می گفتند: این به سبب شایستگیِ خود ماست\nوَإِنْ تُصِبْهُمْ سَیِّئَهٌ یَطَّیَّرُوا بِمُوسَىٰ وَمَنْ مَعَهُ  \nو چون گزند و آسیبی به آنان می رسید، به موسی و همراهانش فال بد می زدند\n أَلَا إِنَّمَا طَائِرُهُمْ عِنْدَ اللَّهِ\nآگاه باشید که سررشته و علت شومی و نحوست فرعونیان که عکس العمل زشتی های خود آنان است نزد خداست.\nوَلَٰکِنَّ أَکْثَرَهُمْ لَا یَعْلَمُونَ\nولی بیشترشان نمی دانند.\n✍️ از اینجا معلوم است کسانی که به صرف دیدن صحنه ای یا شخصی یا عطسه ای ، فکر میکنند حادثه ی بدی برای آنها پیش می آید نظام عالم را نشناخته اند، توحید را نشناخته اند.وجهل عامل این اتفاق است.\n✳️اگر فال بد حق نیست، پس چرا گاهی انسان فال بد میزند و همان اتفاق سرش می آید؟!\nامیرالمومنین علیه السلام در این حکمت میفرماید: خداوند در نظام تکوین کسی را بد شگون خلق نکرده، و فال بد نیز وجود ندارد.\nولی باید دانست، علاوه بر این بحث، بحث دیگری داریم به نام “تاثیر نگاه و ظنّ، در شکل گیری اتفاقات\n🔺 امام رضا علیه السلام: أحسِنِ الظَّنَّ باللّه\nبه خداوند گمان نیک ببر.\n🔺حدیث قدسی:\nفإنّ اللّه عَزَّ و جلَّ یقولُ : أنا عِندَ ظَنِّ عَبدِیَ المُؤمِنِ بی؛ إن خَیرا فخَیرا، و إن شَرّا فَشَرّا\nزیرا خداى عزّ و جلّ مى فرماید : من نزد گمان بنده مؤمن خویشم ؛ اگر گمانِ او به من نیک باشد ، مطابق آن گمان با او رفتار کنم و اگر بد باشد نیز مطابق همان گمانِ بد با او عمل کنم\n✍️ این حسن ظن و سوء ظن ما به خداست که در نظام تکوین اثر دارد. لذا اگر کسی به خدا بد گمان باشد که با شنیدن صدای یک حیوان برای ما مشکلی پیش می آید، به خاطر نگاه و اعتقادش، همان اتفاق می افتد ولی آن اتفاق ارتباطی با فال بد نداشته و بد شگونی نداشته.\n🔺امام صادق علیه السلام:\nالطِّیَرَهُ على ما تَجعَلُها إن هَوَّنتَها تَهَوَّنَت\nتأثیر فال بد به خودت بستگى دارد : اگر آن را آسان بگیرى آسان مى شود\n\n✍️  فال بد اثرش به همان اندازه است که آن را می‌پذیری، اگر آن را آسان بگیری کم اثر خواهد بود و اگر آن را سخت بگیری پر اثر است و اگر به آن اعتنا نکنی، هیچ اثری نخواهد داشت.\n\n✳️ نکوهش شدید روایات از فال بد زدن و تَطَیُّر:\n\n❇️ فال بد زدن، زیر سوال بردن قدرت خدا و شرک است:\nپیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nالطّیرهُ شِرکٌ ولکنّ الله عزّ وجلّ یُذهِبَه بالتوکُّل\nفال بد زدن نوعى شرک است و لیکن خداوند متعال آن را با توکل از بین مى برد.\n🔺در روایت دیگری فرمودند:\nتعطیلی کارها به خاطر فال بد، شرک است.\nپیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nمَن رَدَّتهُ الطِّیَرَهُ عَن حاجَتِهِ فَقَد أشرَکَ\nهر که فال بد زدن او را از کارش باز دارد ، شرک ورزیده است.\n✳️فال بد نزنید، بی حساب وارد بهشت شوید:\nپیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nسَبعونَ ألفا مِن اُمَّتی یَدخُلونَ الجَنَّهَ بغَیرِ حِسابٍ: هُمُ الّذینَ لا یَکتَوُونَ، و لا یَکوُونَ ، و لا یَستَرقُونَ ، و لا یَتَطَیَّرُونَ ، و على ربِّهِم یَتَوَکَّلونَ  \nهفتاد هزار نفر از امّت من بى حساب وارد بهشت مى شوند. آنان کسانى هستند … فال بد نمى زنند و به پروردگارشان توکّل مى کنند.\n❇️ فال بد، اثر روانی دارد و به خود شخص برمیگردد:\nاثر روانی آن هم به من برمیگردد،اگر من منفی باف باشم فال بد زدم اثرش به خودم برمیگردد.درنظام عالم هیچ تاثیری نداردفقط من افسردگی میگیرم وهمیشه استرس دارم.\n🔺در روایتی که در منابع اهل سنت آمده است از پیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم نقل شده:\n لَا طِیَرَهَ، وَإِنَّمَا الطِّیَرَهُ عَلَى مَنْ تَطَیَّرَ\nفال بد زدن حقیقت ندارد، بلکه فال بد تنها بر کسی اثر می‌گذارد که به آن اعتقاد داشته باشد.\n✅ با فال بد زدن، به خودتان آسیب میرسانید.\n❇️ راهکارهای راحت کردن خیال خود از آثار تَطَیُّر:\nاگر احیانا کسی در ذهن یا زبانش نسبت به واقعه ای نفوس بد زد، یا دیگران برای او فال بد زدند، میتواند با انجام دادن اعمالی خیال خودش را راحت کند که اینها اثر ندارند.\n1⃣ بی‌اعتنایی:\nممکن است انسان در ذهن و دلش یک حالت سوئی نسبت به برخی اتفاقات پیدا کند، ولی نباید به آن اعتنا کند و باید از آن درگذرد.\nپیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nإذا تَطَیّرتَ فامْضِ…\nهرگاه فال بد زدى، اعتنایى نکن\n✍️ هر جا فال بد زدی آن را نادیده بگیر و کار خود را دنبال کن.\n2⃣توکل بر خدا:\n برای رهایی از عواقب تطیّر باید انسان به خدا توکل کند.\nتطیّر به کسی ضرر می‌رساند که از آن بترسد ولی کسی که از آن باکی نداشته باشد یقیناً به وی ضرری نخواهد رسید.\nپیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nالطِّیَرَهُ شِرکٌ ، و ما مِنّا إلاّ ! و لکنَّ اللّه یُذهِبُهُ بِالتَّوکُّلِ\nفال بد زدن نوعى شرک است و احدی از ما نیست مگر این که به قلب او تطیّر خطور می‌کند ولی با توکل از بین می‌رود.\n3⃣ دعا:\nاگر انسان دچار حالتی شد که احساس کرد دارد فال بد میزند یا به کسی نسبت بد شگون بودن میدهد باید دعا کند.\nامام کاظم علیه السلام:\nفَمَنْ أَوْجَسَ فِی نَفْسِهِ مِنْ ذَلِکَ شَیْئاً فَلْیَقُلْ:\nهر کس با دیدن مسائلی که در دلش فال بد ایجاد میکند بگوید.\n اِعْتَصَمْتُ بِکَ یَا رَبِّ مِنْ شَرِّ مَا أَجِدُ فِی نَفْسِی فَاعْصِمْنِی مِنْ ذَلِکَ\nپروردگارا از شر این بد دلی که در خود می یابم بتو پناهنده ام مرا از شر آن نگهداری فرما\n4⃣ قرار گرفتن  در ولایت اهل بیت:\nراوی میگود به امام عسکری علیه السلام عرض کردم برخی روزها نحوست دارند، و ما از مسائلی ترس و نگرانی داریم، برای اینکه آسیبی به ما نرسد، چه کنیم؟! فرمود:\nیَا سَهْلُ إِنَّ لِشِیعَتِنَا بِوَلاَیَتِنَا لَعِصْمَهً\nاى سهل شیعۀ ما در پناه ولایت ما مصونند.\nاگر در دریاهای عمیق حرکت کنند، اگر در درّه‌ها و بیابانهاى دوردست میان درنده‌ها و گرگها و دشمنان از جن و انس بروند.\nلَأَمِنُوا مِنْ مَخَاوِفِهِمْ بِوَلاَیَتِهِمْ لَنَا  \nببرکت دوستى و ولایت ما از هر ترسى آسوده‌اند.\n✍️این جمله درواقع ازیک طرف می‌گوید کسانی که محب اهل بیت هستند در حسنند .کسانی که محب اهل بیت هستند منفی بافی از آنها دور است.از طرفی دیگر می‌گوید تو واقعا اگر محب اهل بیت هستی اینگونه نباش.\n\n✳️فال بد نزدن در سیره ی اهل بیت:\n👈جریانی از مسلم بن عقیل:\nابی مخنف در مقتل الحسین مینویسد:\nوقتی امام حسین علیه‌السلام مسلم بن عقیل را به سمت کوفه فرستاد، مسلم دو همراه و راهنما داشت. چون از بیراهه به سمت کوفه میرفتند در بیایان گم شدند و از شدت تشنگی تا نزدیک مرگ رفتند. وقتی به آبادی رسیدند، مسلم نامه ای به امام نوشت و شرح ما وقع را گفت و در پایان عرض کرد:\nوَ قَدْ تَطَیَّرْتُ مِنْ وَجْهِی هَذَا\nمن در این ماموریت احساس بد شگونی دارد و از این حادثه فال بد زده ام.\n🔺حضرت علیه السلام در پاسخ نوشتند که فال بد زدن حقیقت ندارد: فَامْضِ لِوَجْهِکَ الَّذِی وَجَّهْتُکَ لَهُ، وَ السَّلَامُ عَلَیْکَ\nحرکت کن به سمت ماموریتی که به تو داده ام\n✳️تنفر از شیعه به خاطر حرف شین:\n📚علامه ی امینی در جلد 3 الغدیر جریان عجیبی به نقل از “جاحظ” عالم و ادیب بزرگ اهل سنت نقل میکند.\n👈جاحظ میگوید از کسی شنیدم که میگفت:  در کشتی با یکی از تاجران بزرگ همسفر بودم. در طول مسیر هر گاه این پیرمرد نگاهش به یکی از شیعیان داخل کشتی می افتاد آثار بغض و کینه از صورتش هویدا بود.\nروزی به او گفتم: از شیعیان چه چیزی را ناپسند می‌داری؟!\nگفت من فقط از «شین» ابتدای نامشان ناراحت هستم! زیرا من این حرف را تنها در همه شرورها یافته‌ام:\nشَر= بدی\nشُوم =بدیمنی\nشیطان، شَغَب= سر و صدا\nشَقاء =بدبختی\nشِفار =تیزی چاقو\nشَرر =جرقه\nشِین =عیب\nشَوک =خار\nشکوی =شکایت\nشتم =دشنام\nجاحظ به اینجا که میرسد با خوشحالی میگوید: فَمَا ثَبَتَ لِشِیعِیٍّ بَعْدَهَا قَائِمَهٌ\nبعد از این حرف دیگر هیچ شیعه ای نمیتواند کمر راست کند.\nعلامه امینی در واکنش به این سخن میفرماید:\nعَجَبًا مِنْ سَفَاهَهِ الشَّیْخِ ؛ وَأَسْخَفُ مِنَ الشَّیْخِ أَبُو عُثْمَانَ الجاحظ\nتعجب است از این سخن شیخ، و سخیف تر از شیخ ،ابو عثمان الحاجظ است ،به خاطر این تاییدش.\n✍️ کلمات بسیار با “ش” شروع میشوند و معنای مثبتی دارند: نام خدا شاهد است ، شهید ، شکر ، شمس ، شجاعت ، شریعت ، شفا و…\n✍️این خرافات است که یک نفر را نسبت به یک مذهب واعتقاد بدبین میکند.\n✳️روزگار شوم نیست:\n🔺راوی میگوید خدمت حضرت هادی علیه السلام رسیدم، درحالی‌که در مسیر راه انگشتم مجروح شده بود و سواری از کنارم گذشت و صدمه‌ای به شانه‌ام زد و در وسط جمعیتی گرفتار شدم و به سبب آن لباسم پاره شد.\nآن روز را به فال بد گرفتم و گفتم: کَفَانِی اللَّهُ شَرَّکَ\nخدا مرا از شرّ روز بد حفظ کند؛ تو ای روز عجب روز شومی هستی؟\nامام علیه السلام این حرفم را شنید و فرمود:\nیَا حَسَنُ هَذَا وَ أَنْتَ تَغْشَانَا  تَرْمِی بِذَنْبِکَ مَنْ لَا ذَنْبَ لَهُ\nتو با ما ارتباط داری و چنین می‌گویی؟ روز که گناهی ندارد، آن را گناهکار می شمری؟!\nاز شنیدن این سخن به خود آمدم و به خطای خود پی بردم و عرض کردم: «ای مولای من! اینک استغفار می‌کنم و از خدا طلب آمرزش می‌نمایم.»\nامام علیه السلام فرمود:\n یَا حُسْنُ مَا ذَنْبُ الْأَیَّامِ حَتَّى صِرْتُمْ تَتَشَأَّمُونَ بِهَا إِذَا جُوزِیتُمْ بِأَعْمَالِکُمْ فِیهَا\nهنگامی‌که کیفر اعمال شما در این روزها دامن شما را می‌گیرد، روزها چه گناهی دارند که آن را شوم می‌شمارید؟\n✍️این روزگار نیست که نحس باشد،این اتفاقات اطراف ما نیستندکه شوم باشند.برسید به اعمال خودتان.هراتفاقی برایتان می افتد ثمره کارهای خودتان است.خودتان مشکل داشتید،یا بلایی یا امتحانی است،باروزگار چکار دارید،نگاهتان را به عالم دزست کنید.\n✅نکته اول:\nشومی با اعمال انسان ایجاد میشود:\nآنگونه که افراد جاهل حساب میکنند، اتفاقات عالم از صدای حیوانات تا قرمز شدن ماه و… نقشی در شومی ندارند، آن چیزی که اهمیت دارد اعمال انسان است. چه بسا یک نفر با اعمالش خودش را شخصی شوم کرده باشد.\n \n🔺قرآن کریم میفرماید حضرت صالح در پاسخ قوم خود فرمود: قَالَ طَائِرُکُمْ عِنْدَ اللهِ بَلْ أَنْتُمْ قَوْمٌ تُفْتَنُونَ\nسبب بروز مشکلات و بدبختی شما طغیان و گناهان شماست که عکس العملش نزد خداست و ربطی به ما ندارد، بلکه شما گروهی هستید که به مشکلات و مصایب امتحان می شوید شاید به این سبب توبه کنید و مؤمن شوید .\n🔺قرآن کریم در پاسخ به شوم بودن پیامبران میفرماید: قَالُوا طَائِرُکُمْ مَّعَکُمْ\nرسولان گفتند: «شومى شما از خودتان است.\n🔺قرآن کریم در جای دیگر میفرماید: وَ کُلَّ إِنْسَانٍ أَلْزَمْنَاهُ طَائِرَهُ فِی عُنُقِهِ وَنُخْرِجُ لَهُ یَوْمَ الْقِیَامَهِ کِتَابًا یَلْقَاهُ مَنْشُورًا\nو عمل هر انسانی را برای همیشه ملازم او نموده ایم، و روز قیامت نوشته ای را که کتاب عمل اوست برای او بیرون می آوریم که آن را پیش رویش گشوده می بیند.\n ✍️ چه بسا استفاده از لفظ “طائر” که در این آیه آمده است اشاره داشته باشد به خرافاتی که انسانها دارند و خیال میکنند اعمالشان به عهده ی دیگران است.\nقرآن میفرماید فال بد تاثیری ندارد، اعمال شماست که به گردن انسان آویخته شده است.\n✳️ شومی به رفتار هاست:\nپیامبرصَلَّى‌ اللَّهُ‌ عَلَیْهِ‌ وَ‌ آلِهِ‌ وَ‌ سَلَّم:\nشُومُ الْمَرْئَهِ غَلاءُ مَهْرِ‌ها\nزن بدقدم، زنی است که مهرش سنگین است.\n✍️ یعنی اساساً زن‌ها شوم نیستند، بلکه مایه آرامش و انس و دوستی هستند که محیط خانه را به نشاط و آرامش می‌رسانند. ولی وقتی مهریه خانمی زیاد باشد و یا ناسازگاری کند، درواقع خودش مسیر زندگی را به سمت سختی و شومی کشانده است. نه اینکه ذات وجودی مبارکی که خدای متعال خلق کرده، به خودی خود نحس باشد.\n✅نکته دوم:\n⁉️با اینکه خرافات حق نیستند، چرا انسان ها خرافه پرست اند؟!\n🔺استاد شهید مطهری: به نظر من دو خاصیتى که در بشر هست سبب پیدایش فکر نحوست در اشیاء و اعداد شده است:\n⏪یکى اینکه بشر به طور کلى نمى ‏خواهد مسئولیت‏ شکست هاى خودش را متوجه خودش بکند. همیشه دنبال این مى ‏گردد که یک چیز دیگرى پیدا کند و بگوید این بدى، این شکست، این بدبختى که پیدا شد، این من نبودم، این فکر من نبود، این جهل و نادانى من نبود که باعث این شکست شد، یک چیز دیگرى بود. این یک علت بوده است که بشر براى اینکه از تقبل مسئولیت ها فرار کند، آمده است براى اشیاء، براى چهارشنبه، براى ۱۳، براى ۲۵، براى صداى کلاغ، براى صداى جغد نحوست قائل شده است.\n⏪خاصیت دیگر، روح تنبلى است که در انسان مى‏باشد. انسان وقتى بخواهد علت قضایا را بفهمد، باید از طریق علمى و عقلى کاوش و تفکر و جستجو و تفحص کند تا علت واقعى اشیاء را درک کند؛ ولى با خیال، همه قضایا را زود مى ‏شود حل کرد.\nغفر الله لی و لکم، الحمدلله رب العالمین","بخش سوم\nمتن:\nوَ قَالَ (عليه السلام): الْعَيْنُ حَقٌّ، وَ الرُّقَى حَقٌّ، وَ السِّحْرُ حَقٌّ، وَ الْفَأْلُ حَقٌّ؛ وَ الطِّيَرَةُ لَيْسَتْ بِحَقٍّ، وَ الْعَدْوَى لَيْسَتْ بِحَقٍّ؛ وَ الطِّيبُ نُشْرَةٌ، وَ الْعَسَلُ نُشْرَةٌ، وَ الرُّكُوبُ نُشْرَةٌ، وَ النَّظَرُ إِلَى الْخُضْرَةِ نُشْرَةٌ.\nترجمه:\nامام (عليه السّلام) فرمود: «چشم زخم» حق است و تعويذ (دعايى كه براى دفع چشم زخم است) نيز حق است و سِحر حق است و فال (نيك) نيز حق است اما طيره (فال بد) حق نيست و عدوى (اثرگذارى كسى بر ديگرى در امور خرافى نيز) حق نيست. بوى خوش، عسل، سوار شدن بر مركب و نگاه كردن به سبزه، مايه قوت و نشاط است.\nتفسیر:\n🔵خلاصه جلسه قبل:\nوَ قَالَ (علیه السلام): الْعَیْنُ حَقٌّ، وَ الرُّقَى حَقٌّ، وَ السِّحْرُ حَقٌّ، وَ الْفَأْلُ حَقٌّ ؛ وَ الطِّیَرَهُ لَیْسَتْ بِحَقٍّ،\n💠وَ الْعَدْوَى لَیْسَتْ بِحَقٍّ  \nسرایت کردن بیماری حق نیست.\nامیرالمومنین در این حکمت در مورد چهار امری که حقیقت دارند فرمایش داشتند، و دو چیزی که خرافه است و حقیقتی ندارد. یکی فال بد زدن و یکی عَدوی.\n[ «عدوى» به معناى سرایت است به خصوص درمورد سرایت بیمارى از کسى به دیگرى به کار مى رود.]\n✳️شبیه این بخش از حکمت ۴۰۰ در روایت دیگری از پیامبر نیز وارد شده است:\nعَنْ عَلِیِّ بْنِ أَبِی طَالِبٍ ع قَالَ قَالَ رَسُولُ اللَّهِ ص‏ لَا عَدْوَى‏ وَ لَا طِیَرَهَ وَ لَا هَامَ وَ الْعَیْنُ حَقٌّ وَ الْفَالُ حَقٌّ\nسرایت وجود ندارد و فال بد وجود ندارد و هام وجود ندارد و چشم زخم حقیقت دارد و فال نیک حقیقت دارد.\n❇️ اگر چه همه بخش های این حکمت سنگین و پیچیده و دارای توضیح فراوان بود، ولی این بخش به طور خاص از پیچیدگی های خاصی برخوردار است که اتفاقا محل ایجاد شبهه برای نهج البلاغه پژوهان و حتی معاندان و مخالفان شده است.\nمعنای مشهور و تحت اللفظی این جمله آن است که “ما چیزی به نام بیماری مُسری نداریم” و در واقع حضرت نفی میکنند بیماری مُسری را.\n⏪نظرات در مورد معنای جمله\n” الْعَدْوَى لَیْسَتْ بِحَقٍّ “\n1⃣ مقصود ظاهر کلام حضرت است، هیچ بیماری مُسری نداریم.\nاین افراد با نوشتن مقاله هایی مثل “بیماری مسری چیست و آیا سرایت بیماری حقیقت دارد؟”\nدر صدد بیان این مطلب هستند که اصلا چیزی به نام سرایت بیماری وجود ندارد، بیماری در هوا، آب و موارد غذایی وجود دارد و متناسب با سیستم ایمنی افراد، آنها را مبتلا میکند یا خیر.\n⏪دلیل این افراد دو چیز است:\nاولا؛ به تجربه ثابت شده همه کسانی که با یک بیمار مُسری مواجه میشوند، بیمار نمیشوند و فقط برخی بیمار میشوند.\nثانیا ؛ روایاتی در این باب داریم:\n📗 مرحوم مجلسی در بحار نقل میکند:  أَنَّ امْرَأَهً سَأَلَتْ بَعْضَ أَزْوَاجِهِ صلی الله علیه و آله عَنِ الْفِرَارِ مِنَ الْمَجْذُومِ فَقَالَتْ کَلَّا وَ اللَّهِ\nزنی از همسران آن حضرت درباره گریز از جذامی پرسش کرد و او جواب داد:\nنه، به خدا سوگند هرگز\n وَ قَدْ قَالَ رَسُولُ اللَّهِ صلی الله علیه و آله لا عَدْوَی  \nو رسول خدا فرموده: سرایت وجود ندارد.\n وَ قَدْ کَانَ لَنَا مَوْلًی أَصَابَهُ ذَلِکَ وَ کَانَ یَأْکُلُ فِی صِحَافِی وَ یَشْرَبُ مِنْ قِدَاحِی وَ یَنَامُ عَلَی فِرَاشِی\nو ما یک خدمتکار داشتیم که دچار آن شد و در کاسه من غذا می‌خورد و از ظرف آبم می‌نوشید و بر بسترم می‌خوابید.\n📗در روایت داریم:\nأَنَّهُ صَلَّى اللَّهُ عَلَیْهِ وَ آلِهِ أَخَذَ بِیَدِ مَجْذُومٍ وَ قَالَ بِسْمِ اَللَّهِ ثِقَهً بِاللَّهِ وَ تَوَکُّلاً عَلَیْهِ وَ أَدْخَلَهَا مَعَهُ اَلصَّحْفَهَ\nپیامبر دست فردی که مبتلابه جذام بود را گرفته و فرمود:  یعنی با نام خدا و اعتماد و توکل بر پروردگار و سپس با او در یک کاسه هم غذا شد.\n📗 در حالات امام سجاد داریم، روزی امام از کنار چند نفر جذامی که مشغول غذا خوردن بودند، عبور می‌کرد. آن‌ها امام را به خوردن غذا دعوت کردند.\nامام پاسخ داد: اگر روزه نداشتم، می‌خوردم!\nسپس وقتی به منزل رسید دستور داد تا غذایی تهیه کنند و در تهیه غذا هر چه می‌توانند از خرج مضایقه نکنند و آن مبتلایان به جذام را به منزل خود دعوت نموده؛\nفَاَطْعَمَهُمُ ثُمَّ اَعْطَاهُم‌\nو به همراه آنان غذا خورد و به آنان عطا کرد.\n⏪ این نظریه قائل است، دنیای پزشکی امروز با ترفند “مُسری معرفی کردن بیماری ها” و “ترس فروشی” در صدد تجارت و فروش واکسن و… است.\nولی به هر دو دلیل این گروه ایراد وارد است:\n◀️ اولا؛ بیماری مسری است ولی، به علت ضعف و قدرت سیستم ایمنی، برخی دچار میشوند و برخی خیر.\n◀️ثانیا؛ همنشینی اهل بیت با جزامی ها از دو جهت قابل بررسی است:\n1⃣ توکل بالای اهل بیت و جایگاه آنان که باید همه افراد را جذب کنند؛ و شاید این حکم مخصوص آنهاست.\n2⃣ چه بسا همنشینی اهل بیت با جزامی ها بعد از گذشت دوره ی انتقال بوده است، و دیگر بیماری سرایت نمیکرده است.\n3⃣ چه بسا اهل بیت به خاطر قوت و قدرت جسمی و روحی در مواجهه با بیماری مستحکم بوده اند.\n4⃣ روایات متعارض فراوان تر است و در حجیت این روایات خدشه وارد میکند.\n⏪نظرات در مورد معنای جمله\n” الْعَدْوَى لَیْسَتْ بِحَقٍّ “\n2⃣ دومین نظر؛ مقصود ظاهر کلام حضرت نیست، و باید دنیال معنایی دیگر بود.\nاز آنجایی که امروزه ثابت شده است که “بیماری مُسری داریم”، شرح و توضیح این بخش از حکمت نیاز به دقت بیشتری دارد.\n♻️ بیماری های مُسری در زمان اهل بیت.\nبرای اینکه مشخص شود مقصود امیرالمومنین از این فرمایش بیماری های مُسری مثل سرماخوردگی و آنفولانزا و … نیست ابتدا باید ثابت کنیم اهل بیت علم به بیماری مسری و عوارض آن داشته اند و در این مورد توصیه هایی از آنها رسیده است.\n1⃣طاعون واگیر دار اردن:\nمَاتَ مُعَاذُ بْنُ جَبَلٍ بِنَاحِیَهِ الْأُرْدُنِّ فِی طَاعُونِ عَمَوَاسَ سَنَهَ ثَمَانَ عَشْرَهَ\nمعاذ بن جبل در منطقه اردن در طاعون عمواس در سال هجده هجری درگذشت.\nدر این طاعون که بسیار گسترده و فراگیر شد افراد دیگری مانند بلال حبشی نیز از دنیا رفتند و برخی قربانیان این بیماری واگیر دار را تا ۲۵ هزار نفر نقل کرده اند.\n2⃣ وبای واگیردار عراق:\n اَلْمُعَلَّى بْنِ خُنَیْسٍ قَالَ: کُنْتُ عِنْدَ أَبِی عَبْدِ اَللَّهِ عَلَیْهِ السَّلاَمُ فِی بَعْضِ حَوَائِجِی فَقَالَ لِی مَا لِی أَرَاکَ کَئِیباً حَزِیناً  \nخدمت حضرت صادق براى کارى رفته بودم فرمود چرا افسرده هستى؟\nفَقُلْتُ مَا بَلَغَنِی عَنِ اَلْعِرَاقِ مِنْ هَذَا اَلْوَبَاءِ أَذْکُرُ عِیَالِی\nعرض کردم شنیده‌ام در عراق وبا آمده دلم بجانب زن و بچه‌ام پرواز کرده.\nقَالَ فَاصْرِفْ وَجْهَکَ فَصَرَفْتُ وَجْهِی\nفرمود صورت خود را برگردان.صورت برگرداندم.\nقَالَ ثُمَّ قَالَ اُدْخُلْ دَارَکَ\nفرمود داخل خانه شو.\nقَالَ فَدَخَلْتُ فَإِذَا أَنَا لاَ أَفْقِدُ مِنْ عِیَالِی صَغِیراً وَ لاَ کَبِیراً\nوارد خانه شدم تمام خانواده‌ام از کوچک و بزرگ حضور داشتند.\nإِلاَّ وَ هُوَ فِی دَارِی بِمَا فِیهَا   \nخانه‌ام همان وضع سابق را داشت.\nثُمَّ خَرَجْتُ فَقَالَ لِی اِصْرِفْ وَجْهَکَ فَصَرَفْتُهُ فَنَظَرْتُ فَلَمْ أَرَ شَیْئاً\nاز خانه بیرون آمدم فرمود صورت خود را برگردان نگاه کردم چیزى ندیدم.\n♻️مراقب سرایت بیماری های مُسری باشید.\nپیامبر صلی الله علیه واله فرمود:\nإِذَا سَمِعْتُمُ الطَّاعُونَ بِأَرْضٍ، فَلا تَدْخُلُوهَا هرگاه شنیدید که در سرزمینی طاعون آمده است، به آنجا نروید،\nوَإِذَا وَقَعَ بِأرْضٍ وأنْتُمْ فِیهَا، فَلا تَخْرُجُوا مِنْهَا\nو هرگاه در سرزمینی بودید و طاعون در آنجا شیوع پیدا کرد، آنجا را ترک نکنید.\nهر دو دستور این روایت برای جلوگیری از گسترش بیماری های واگیردار است.\n❎ البته از این روایت نمیتوان حرمت خروج را برداشت کرد چون امام صادق در شرح این حدیث فرمود این حکم پیامبر برای منع خروج، برای جلوگیری از نفوذ دشمن بوده ،\nالْفَارُّ مِنْهُ کَالْفَارِّ مِنَ الزَّحْفِ\n❎ قرنطینه برای جلوگیری از انتشار بیماری. پیامبر خدا ص فرمود:\nإِذَا وَقَعَ اَلطَّاعُونُ فِی أَهْلِ مَسْجِدٍ فَلَیْسَ لَهُمْ أَنْ یَفِرُّوا مِنْهُ إِلَى غَیْرِهِ.\nاگر در بین مردمى که در مسجد هستند طاعون پیدا شود حقّ‌ ندارند از آن مسجد بگریزند و به مسجد دیگر بروند.\nمقصود آن است که دیگر مکان ها آلوده به بیماری نشوند.\n❎از جزامی ها فاصله بگیرید.\nپیامبر صلی الله علیه واله فرمود: \nلا تُدیمُوا النَّظَرَ إلَى المُجَذَّمینَ‌،\nبه جذامیان، خیلى نگاه نکنید،\nو إذا کَلَّمتُموهُم فَلیَکُن بَینَکُم و بَینَهُم قیدُ رُمحٍ\nو چون با آنان سخن مى‌گویید، باید میان شما و آنها به اندازه بندِ نیزه، فاصله باشد.\nجزام بیماریی است مُسری که مهمترین راه انتقال آن تنفس است.\n❎فاصله گرفتن پیامبر از جزامی:\nدر روایت دیگر از پیامبر داریم:\nاَتَاهُ مَجْذُومٌ لِیبَایعَهُ فَلَم‌ یمُدَّ یدَهُ اِلَیهِ بَلْ قَالَ اَمْسِک یدَک فَقَدْ بَایعْتُک\nشخصی که مبتلابه جذام بود برای بیعت نزد پیامبر آمد، اما حضرت به او دست نداده و فرمودند: بدون آن که با من دست بدهی، بیعتت را پذیرفتم.\n♻️نکاتی عجیب در مورد علم اهل بیت به بیماری ها:\nبیماری وبا برای اولین بار حدود 500 سال پیش به عنوان یک بیماری مُسری کشف شد.\nامیرالمومنین در خطبه  ۱۷۵ میفرماید:\nکَأَنَّکُمْ نَعَمٌ أَرَاحَ بِهَا سَائِمٌ إِلَى مَرْعًى وَبِیٍّ وَ مَشْرَبٍ دَوِیٍّ\nگویا شما گله شتران یا گوسفندانى هستید که چوپان، آن ها را به چراگاه «وباخیز» و چشمه اى بیمارى زا مى برد.\n ♻️حدود 200 سال پیش برای اولین بار ماندگاری طولانی مدت وبا در آب کشف شد.\nامیرالمومنین در خطبه ۱۶۲ میفرماید:\nحَاوَلَ الْقَوْمُ إِطْفَاءَ نُورِ اللَّهِ مِنْ مِصْبَاحِهِ اهل شام کوشیدند نور خدا را که از چراغش مى درخشید خاموش سازند.\n وَ سَدَّ فَوَّارِهِ مِنْ یَنْبُوعِهِ\nو مجراى فَوَران چشمه فیض الهى را مسدود کنند،\nوَ جَدَحُوا بَیْنِی وَ بَیْنَهُمْ شِرْباً وَبِیئاً\nو این آب زلال را میان من و خودشان به بیمارى ها و سموم آلوده سازند.\n♻️ دعای صحیفه سجادیه امام سجاد به دشمنان نفرین میکند که:\nاللَّهُمَّ وَ امْزُجْ مِیاهَهُمْ بِالْوَبَاءِ\nبارخدایا آب آشامیدنی آنان را به وبا مخلوط کن.\n❇️از مجموع این روایات دو نکته قابل استفاده است:\nاولا؛ اهل بیت علم به مُسری بودن بیماری ها داشته اند و برای در امان ماندن مردم از بیماری های مُسری دستورات مهمی ارائه کرده اند.\nثانیا ؛ معنای کلام حضرت در حکمت ۴۰۰ چیزی غیر از معنای ظاهری آن است.\n \n◀️ الف. نفی نظریه ی خرافی جاهلیت در مورد سرایت  کل بیماریها:\n آیت الله مکارم:\nحضرت این مطلب را در مقابل یک اعتقاد خرافی و افراطی در عصر جاهلیت مطرح کرده اند.\nعده ای باور داشته اند که همه بیماری ها واگیردار هستند و کلا از رفت و آمد و عیادت بیماری خودداری میکردند،\nلذا حضرت در پاسخ به نظریه ی باطل آنها میفرماید “سرایت پذیری کل بیماری ها حق نیست”\nلذا حضرت سرایت پذیری برخی بیماری ها مثل شکسته شدن دست، لنگ بودن پا، کوری و… را نفی میکند.\n◀️ ب. نفی نظریه ی استقلال بیماری و خروج از مشیّت الهی:\nگروهی بیماری را موجودی میدانند که از دایره قدرت خداوند خارج شده و استقلال در سرایت دارد، در حالی که میدانیم تمام ذرات عالم فرمانبردار خداوند هستند و به اراده ی او کار میکنند.\n📗در “کتاب الماء”  که اولین کتاب لغت اصطلاحات پزشکی عربی است دارد:\nوَاخْتَلَفُوا فِی مَعْنَى قَوْلِهِ “لَا عَدْوَى”\nو بزرگان در معنای «لا عَدْوَى»\n_بیماری خودبه‌خود سرایت نمی‌کند_ اختلاف کردند.\nوَ أَظْهَرُ مَا قِیلَ فِی ذَلِکَ أَنَّهُ نَفْیٌ لِمَا کَانَ یَعْتَقِدُهُ أَهْلُ الْجَاهِلِیَّهِ مِنْ أَنَّ هَذِهِ الْأَمْرَاضَ تُعْدِی بِطَبْعِهَا مِنْ غَیْرِ اعْتِقَادِ تَقْدِیرِ اللَّهِ لِذَلِکَ\nآشکارترین سخنی که در این باره گفته شده، این است که این جمله، نفی آن چیزی است که اهل جاهلیت اعتقاد داشتند؛ که این بیماری‌ها به طور ذاتی و بدون اعتقاد به تقدیر خداوند سرایت می‌کنند.\n📗بیماری و سرایت آن به اراده ی خدا اتفاق می افتد.\nمرحوم کلینی در کافی روایت میکند که شخص شتربانی به امام صادق عرض کرد:\nشترانی‌ دچار بیماری‌ جرب _کچلی‌ پوست_ هستند و من آنها را از میان شتران خود کنار میکنم از ترس اینکه بیماری‌ جرب آنها بشتران دیگر سرایت کند؟\nامام صادق فرمود من پاسخ پیامبر را به تو میدهم:\n↩️یک اعرابی‌ نزد رسول خدا آمد و عرض کرد یا رسول اللّٰه من گوسفند یا گاو یا شتری‌ را که بیماری‌ جرب دارد به بهای‌ اندک بدست می‌‌آورم و از خریدن آن‌ها نگرانم و بدم می‌‌آید از بیم اینکه این جرب آن‌ها بیشتر و گوسفند سالم خودم سرایت کند.\n↩️پیامبر در پاسخ به این شخص فرمود:\nیَا أَعْرَابِیُّ فَمَنْ  أَعْدَی‌  اَلْأَوَّلَ؟ \nای‌ اعرابی‌ پس این بیماری‌ از چه کسی‌ و از کجا به آن اولی‌ سرایت کرده است؟\n↩️ این حدیث به خوبی نشان میدهد منظور از عَدوی، توجه به مشیت و اراده ی الهی است. یعنی خداوند است که بنا بر مصالحی شخصی را بیمار میکند یا خیر.\n📗علامه مجلسی در مرآه العقول که شرح کافی میفرماید:\nمنظور از عدوی نفی مُسری بودن بیماری نیست؛\nبَلْ نَفْیُ اسْتِقْلَالِ تَأْثِیرِهِ، بَلْ هُوَ مُتَعَلِّقٌ بِمَشِیئَهِ اللَّهِ.\nبلکه منظور نفی استقلال در تأثیر آن بیماری است، بلکه تأثیر آن مربوط به مشیت خداوند است.\nوَ أَرَى هَذَا الْقَوْلَ أَوْلَى؛\nو من این گفتار را شایسته‌تر می‌دانم؛\nلِمَا فِیهِ مِنَ التَّوْفِیقِ بَیْنَ الْأَحَادِیثِ، وَالْأُصُولِ الطِّبِّیَّهِ الَّتِی وَرَدَ الشَّرْعُ بِاعْتِبَارِهَا عَلَى وَجْهٍ لَا یُنَاقِضُ أُصُولَ التَّوْحِیدِ.\nزیرا در آن، جمع بین احادیث و اصول پزشکی است که شرع اصول پزشکی را محرم میشمارد تا وقتی که با توحید مشکل نداشته باشند.\n◀️ ج. نفی نظریه ی انتقال بیماری از شخصی به شخص دیگر به سبب سحر و جادو:\n میرزا مهدی صادقی: از آنجایی که بحث در مورد چشم زخم ، حرزها، سحر و جادو، فال نیک زدن و فال بد زدن بود؛\nاین بخش را نیز باید مرتبط با همان مسائل دانست _نه اینکه به یکباره این بخش را مربوط به بیماری های جسمی مرسوم بدانیم.\n↩️ایشان معتقد است : سحر و جادو و چشم زخم توان برداشتن بیماری از شخصی و انتقال آن به شخص دیگر را ندارند.\n↩️اینکه گروهی میگویند ما با سحر و مسائل ماورایی میتوانیم بیماری تو را به جان دشمنت بیندازیم، چشم زخمی که به تو اصابت کرده را به سمت دشمنت هدایت کنیم؛ اینها واقعیت ندارند و چنین چیزی ممکن نیست.\n⏪ داستان قوز بالا قوز:\nدر افسانه ها آمده است که دو رفیق بودند که قوز داشتند، یکی از آنها به حمام رفت و دید اجنه جشن دارند؛ او هم همراه آنان مشغول به شادی و رقص شد؛ جنیان خوششان آمد و قوز او را برداشتند.\n↩️فردا روزی که دوستش را دید و او از برطرف شدن قوزش پرسید، گفت ماجرا این است.\nاو هم به حمام رفت و مشغول رقص و شادی شد؛ غافل از اینکه جنیان آن روز عزا داشتند و قوز ـآن شخص را هم روی قوز این گذاشتند و شد قوز بالا قوز.\nاین داستان از دو جهت خرافه و باطل است:\n1⃣ “وَ الْعَدْوَى لَیْسَتْ بِحَقٍّ ” ؛\nانتقال دادن بیماری از شخص دیگر شدنی نیست و باطل است.\n2⃣ حمام جن ندارد.\nدر کتاب کافی از امام صادق علیه السلام نقل است:\nلَیْسَ مِنْ بَیْتٍ فِیهِ حَمَامٌ إِلاَّ لَمْ یُصِبْ أَهْلَ ذَلِکَ اَلْبَیْتِ آفَهٌ مِنَ اَلْجِنِّ\nهر خانه‌اى که در آن کبوتر باشد، آسیبى از جنیان به اهل آن خانه نمى‌رسد؛\nإِنَّ سُفَهَاءَ اَلْجِنِّ یَعْبَثُونَ فِی اَلْبَیْتِ فَیَعْبَثُونَ بِالْحَمَامِ وَ یَدَعُونَ اَلْإِنْسَانَ\nچرا که جنیان نادان و سفیه در خانه‌ها بازى مى‌کنند، پس با کبوتر بازى مى‌کنند و انسان را وامى‌گذارند.\n❇️ برخی فرق بین “حَمام” و “حمّام” را نمیدانسته اند و خیال میکردند اجنه در حمّام هستند.\nلازم به ذکر است در زمانهای گذشته هر خانه یکی حمّام نداشت بلکه هر روستا یک حمّام داشت.\n💠وَ الطِّیبُ نُشْرَهٌ،\nبوى خوش،\n💠وَ الْعَسَلُ نُشْرَهٌ،\nعسل، مایه نشاط است.\n💠وَ الرُّکُوبُ نُشْرَهٌ،\nسوار شدن بر مرکب،\n💠 وَ النَّظَرُ إِلَى الْخُضْرَهِ نُشْرَهٌ\nو نگاه کردن به سبزه، مایه قوت و نشاط است.\n✳️بعد از آنکه حضرت در مورد چهار مطلب حق و دو مطلب خرافی بیانات کوتاه و پر مضمونی ارائه فرمودند،در بخش پایانی به چهار مورد از موارد نشاط آفرین اشاره میفرماید.\n♻️معنای نُشره:\n نُشرَه در اصل از ماده «نشر» گرفته شده است به معنای “حرز و رُقیِه”ای  که سبب انتشار آثار مثبت در شخص میشود.\n🔰مرحوم مصطفوی در کتاب التحقیق ، نُشره را به معنای گسترده تری میداند که «هُوَ بَسْطٌ بَعْدَ قَبْضٍ».\nعلامه مجلسى نیز آن را به چیزى که سبب زوال غم و اندوه میشود تفسیر کرده است.\nخلاصه آنکه نُشره به معنای هر چیزی است که مانند حرز عمل میکند و باعث از بین رفتن غم و غصه و ایجاد نشاط میشود.\n✳️ نشاط باعث برطرف شدن غصه هاست.\nبخشی از تعویذها و حرزها، ادعیه و دعاهای ماثور هستند.\nولی حضرت در اینجا به چند حرز دیگر نیز اشاره میکنند که سبب برطرف شدن غم هستند\nبوى خوش ؛ عسل ؛ سوار شدن بر مرکب راهوار و نگاه کردن به سبزه\n✅ گویى این چهار موضوع همچون حرز و تعویذى است که غم و اندوه را از انسان زایل مى کند و این موضوع علاوه بر این که به تجربه ثابت شده هم اکنون مورد تأکید پزشکان براى رفع غم واندوه وافسردگى و تجدید نشاط بعد از خستگى مى باشد.\n⏪ارتباط این چهار جمله با بحث های قبلی چیست؟\nامیرالمومنین در این حکمت جملاتی را پشت سر هم به کار میبرند، طبیعی است یک گوینده عادی نیز در سخن گفتن، ارتباط بین جملات را باید رعایت کند چه رسد به امیرالمومنین که امیر کلام است. \n↩️ بزرگان میفرمایند: تاثیرات سحر و جادو دو بخش است؛\nبخش عمده ای به روح و روان و ذهنیت بافی منفی انسان بر میگردد؛ و بخش دیگری در مورد واقعیت ها است.\nیعنی با سحر کاری میکنند که انسان همیشه ترس از بیماری یا فقر داشته باشد؛ یا واقعا او را فقیر و بیمار میکنند.\n↩️حضرت در این بخش میفرماید شما با عوامل نشاط آور میتوانید بخش عمده ای از سحر را که مربوط به روان است ابطال کنید.\n1⃣ عطر و بوی خوش\nوَ الطِّیبُ نُشْرَهٌ\nهر بوی خوشی نشاط آور نیست بلکه برخی بوهای خوش مثل ادکلن ها به خاطر مسائل شیمیایی که دارند خودشان کسالت آور و چه بسا مقدمه ساز سحر و جادو باشند.\nولی عطرهای طبیعی اسلامی، نشاط آور اند.\nدر حکمت 397 به طور مفصل در مورد انواع عطرهای اسلامی توضیح داده شد که مشک و عنبر و عود و زعفران و گلاب و … است. استفاده از این عطرها نشاط آور و نوعی حرز است برای برطرف شدن چشم زخم ها و سحرها.\n2⃣ عسل\nوَ الْعَسَلُ نُشْرَهٌ\nقرآن کریم میفرماید:\n《یَخْرُجُ مِن بُطُونِهَا شَرَابٌ مُّخْتَلِفٌ أَلْوَ نُهُ فِیهِ شِفَاءٌ لِّلنَّاسِ؛ نحل – ۶۹》\nاز دل زنبور عسل ، نوشیدنى اى به رنگ هاى گوناگون ، بیرون مى آید که در آن براى مردم ، درمان است.\n✳️ پیامبر صلی الله علیه وآله فرمود:\nإنَّ اللّهَ عز و جل جَعَلَ البَرَکَهَ فِی العَسَلِ خداوند، برکت را در عسل قرار داده است ، و فیهِ شِفاءٌ مِنَ الأَوجاعِ ، وقَد بارَکَ عَلَیهِ سَبعونَ نَبِیّا\nشفاى دردها در آن است و هفتاد پیامبر براى برکت آن ، دعا کرده اند.\n✳️ پیامبر صلی الله علیه وآله فرمود:\nما طُلِبَ الدَّواءُ بِشَیءٍ أفضَلَ مِن شَربَهِ عَسَلٍ\nاز هیچ چیزى همانند شربتى از عسل، درمان نجسته اند.\n✳️ پیامبر صلی الله علیه وآله فرمود:\nعَلَیکُم بِالشِّفاءَینِ : العَسَلِ ، وَالقُرآنِ\nبر شما باد دو درمان: عسل و قرآن.\nوَ نُنَزِّلُ مِنَ الْقُرْآنِ ما هُوَ شِفاءٌ وَ رَحْمَهٌ لِلْمُؤْمِنِینَ‌…\n✳️امیرالمومنین سلام الله علیه فرمود:\nالعَسَلُ شِفاءٌ مِن کُلِّ داءٍ ، ولا داءَ فیهِ عسل ، درمان هر دردى است و هیچ بیمارى اى در آن نیست ؛\nیُقِلُّ البَلغَمَ و یَجلُو القَلبَ\nبلغم را مى کاهد و دل را روشن مى کند.\n ↩️صابون‌ها و شوینده‌هایی که امروزه رایج است و عموماً با موارد شیمیایی ساخته می‌شوند اگر ضرر نداشته باشند فایده اینچنین هم ندارند\n3⃣ سوار کاری مایه نشاط است.\nوَ الرُّکُوبُ نُشْرَهٌ\nپیامبر صلوه الله علیه فرمود:\nاَلْخَیْرُ مَعْقُودٌ بِنَوَاصِی اَلْخَیْلِ إِلَى یَوْمِ اَلْقِیَامَهِ\nخیر تا روز رستاخیز به پیشانی اسبان بسته شده است.\n_✳️پیامبر صلی الله علیه وآله فرمود: \nمِنْ سَعَادَهِ اَلرَّجُلِ اَلْمُسْلِمِ اَلْمَرْکَبُ اَلْهَنِیءُ\nاز خوشبختی مرد مسلمان داشتن یک مرکب سواری راحت می باشد.\n✳️پیامبرصلی الله علیه وآله فرمود::\nمَا مِنْ فَرَسٍ إِلاَّ وَ یُؤْذَنُ لَهُ عِنْدَ کُلِّ فَجْرٍ\nهیچ اسبی نیست مگر آنکه در هنگام طلوع فجر مناجات نموده و می گوید :\nاَللَّهُمَّ مَنْ خَوَّلْتَنِی مِنْ بَنِی آدَمَ وَ جَعَلْتَنِی لَهُ فَاجْعَلْنِی أَحَبَّ مَالِهِ وَ أَهْلِهِ إِلَیْهِ\nای خدایی که مرا واگذار و در تسخیر بنی آدم قرارداده ای ، بهترین مالها و دوست داشتنی ترین آنها را در نزد صاحبم قرار ده. \n⏪ توصیه به اسب سواری:\n↙️* از جهتی میتواند به عنوان یک تفریح، سرگرمی و ورزش حساب شود که خودش باعث نشاط خواهد شد و در برطرف شدن مشکلات و غم ها کمک میکند.\n↙️ از جهت دیگر نیز شاید این حیوان خصوصیت خاصی داشته باشد که برای غم زدایی و حتی تاثیر بر روی سحر و جادو و چشم زخم مفید باشد که این مطلب جای تحقیق و بررسی دارد.\n↙️ به نظر میرسد آنچه باعث نشاط است پرورش و سوارکاری است، و شاید درست نباشد اگر بگوییم در گذشته وسیله ی نقلیه ی اسب بوده، و امروز هم استفاده از وسیله نقلیه همان حکم را دارد.\nزیرا در گذشته شتر نیز بوده ولی تاکید روی اسب است.\n4⃣ نگاه به سبزه\nوَ النَّظَرُ إِلَى الْخُضْرَهِ نُشْرَهٌ\nقرآن کریم میفرماید:\n《وَأَنْزَلَ لَکُمْ مِنَ السَّمَاءِ مَاءً فَأَنْبَتْنَا بِهِ حَدَائِقَ ذَاتَ بَهْجَهٍ 》\nو برای شما از آسمان، آبی فرستاد که با آن، باغهایی زیبا و سرورانگیز رویاندیم.\n✳️امام کاظم سلام الله علیه فرمود:\nثَلاثٌ یَجلِینَ البَصَرَ : اَلنَّظرُ إلَى الخُضرَهِ   سه چیز دیده را روشن کند :\nبه سبزه نگریستن\nوَالنَّظَرُ إلَى الماءِ الجاری\nبه آب روان نگریستن\n وَالنَّظَرُ إلَى الوَجهِ الحَسَنِ\nو به روى زیبا نگریستن.\n📗 در مورد پیامبر روایت داریم:\nکان یُعجِبُه الثیاب الخُضر و أَکْثَرُ ثِیَابِهِ اَلْبَیَاضُ\nلباس‌هاى سبز حضرت را شگفت‌زده مى‌نمود، لیکن بیشتر لباس‌هاى رسول ‌الله سفید بوده است.\n⏪ از منظر علوم روز و روانشناسی رنگ‌ها؛ رنگ سبز به عنوان رنگ تعادل و آرامش شناخته می‌شود. این رنگ باعث کاهش استرس و ایجاد احساس امنیت می‌گردد.\nقرآن کریم درباره لباس بهشتیان مى‌فرماید:\n《 عٰالِیَهُمْ‌ ثِیٰابُ‌ سُندُسٍ‌ خُضْرٌ؛ انسان – ۲۱ 》\nبر اندام بهشتیان لباس حریر نازک و سبز مى‌باشد.\n📗در توحید مفضل امام صادق در مورد طبیعت میفرماید:\nای مفضّل نظر کن در نباتات و انواع منافعی که خدا در آنها مقرّر ساخته، پس میوه ها را برای غذا آفریده و کاه ها را برای علف حیوانات و هیزم را برای برافروختن آتش و چوب را برای اصناف نجّاری ها و پوست درختان و برگ و ریشه و ساق و صمغ آنها را برای انواع منفعت ها.\n↩️اگر میوه ها همه روی زمین درست میشدند و درختی نداشتند، اگرچه ما میوه داشتیم ولی منفعت های زیادی را از دست میدادیم.\nهَذَا مَعَ مَا فِی النَّبَاتِ مِنَ التَّلَذُّذِ بِحُسْنِ مَنْظَرِهِ وَ نَضَارَتِهِ الَّتِی لَا یَعْدِلُهَا شَیْ‏ءٌ مِنْ مَنَاظِرِ الْعَالَمِ وَ مَلَاهِیهِ\nو اینها منفعت های عظیم است قطع نظر از لذتی که آدمی از دیدن گیاه های سبز و درختان خرم و گل های رنگارنگ و شکوفه های گوناگون حاصل می شود که هیچ لذتی را با آن برابر نمی توان کرد.\n↩️ شاید مقصود از این بخش مطلق تفریح و مسافرت باشد که در برطرف شدن مشکلات روحی موثر است و طبیعتا در دفع سحر و جادو نیز نقش خواهد داشت\n💠وَ قَالَ (علیه السلام): الْعَیْنُ حَقٌّ «چشم زخم» حق است ،\n💠 وَ الرُّقَى حَقٌّ  \nو تعویذ _دعایى که براى دفع چشم زخم است_ نیز حق است.\n💠 وَ السِّحْرُ حَقٌّ\nو سِحر حق است،\n💠وَ الْفَأْلُ حَقٌّ\nو فال نیک زدن نیز حق است ؛\n💠وَ الطِّیَرَهُ لَیْسَتْ بِحَقٍّ  \nاما فال بد زدن حق نیست،\n💠وَ الْعَدْوَى لَیْسَتْ بِحَقٍّ\nسرایت کردن بیماری حق نیست.\n💠وَ الطِّیبُ نُشْرَهٌ،\nبوى خوش،\n💠 وَ الْعَسَلُ نُشْرَهٌ،\nعسل، مایه نشاط\n💠وَ الرُّکُوبُ نُشْرَهٌ،\nوسوار شدن بر مرکب\n💠وَ النَّظَرُ إِلَى الْخُضْرَهِ نُشْرَهٌ\nو نگاه کردن به سبزه، مایه قوت و نشاط است."]});
